      // カウントダウンタイマー
      // ----------------------------------
      function startNextRaceCountdown() {
        const timerDays = document.getElementById('timer-days');
        const timerHours = document.getElementById('timer-hours');
        const timerMinutes = document.getElementById('timer-minutes');
        const timerSeconds = document.getElementById('timer-seconds');
        
        const nextRaceName = document.getElementById('next-race-name');
        const nextRaceMeta = document.getElementById('next-race-meta');
        const btnHeroPred = document.getElementById('btn-hero-prediction');
        
        function updateCountdown() {
          const now = new Date();
          const upcomingRaces = G1_RACES
            .filter(r => new Date(r.date) > now)
            .sort((a, b) => new Date(a.date) - new Date(b.date));
            
          if (upcomingRaces.length === 0) {
            if (nextRaceName) nextRaceName.innerText = '2026年 G1レース全日程終了';
            if (nextRaceMeta) nextRaceMeta.innerText = '全レースのご声援ありがとうございました';
            if (timerDays) timerDays.innerText = '00';
            if (timerHours) timerHours.innerText = '00';
            if (timerMinutes) timerMinutes.innerText = '00';
            if (timerSeconds) timerSeconds.innerText = '00';
            if (countdownInterval) clearInterval(countdownInterval);
            return;
          }
          
          const nextRace = upcomingRaces[0];
          const raceTime = new Date(nextRace.date);
          const diffMs = raceTime - now;
          
          if (nextRaceName) nextRaceName.innerText = nextRace.name;
          if (btnHeroPred) btnHeroPred.innerHTML = `🎯 ${nextRace.name} 予想・攻略を見る`;
          
          const formattedDate = new Date(nextRace.date).toLocaleDateString('ja-JP', {
            year: 'numeric',
            month: 'long',
            day: 'numeric',
            weekday: 'short'
          });
          if (nextRaceMeta) {
            nextRaceMeta.innerText = `開催日: ${formattedDate} 15:40発走 | ${nextRace.location}競馬場 (${nextRace.course})`;
          }
          
          const days = Math.floor(diffMs / (1000 * 60 * 60 * 24));
          const hours = Math.floor((diffMs % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
          const minutes = Math.floor((diffMs % (1000 * 60 * 60)) / (1000 * 60));
          const seconds = Math.floor((diffMs % (1000 * 60)) / 1000);
          
          if (timerDays) timerDays.innerText = String(days).padStart(2, '0');
          if (timerHours) timerHours.innerText = String(hours).padStart(2, '0');
          if (timerMinutes) timerMinutes.innerText = String(minutes).padStart(2, '0');
          if (timerSeconds) timerSeconds.innerText = String(seconds).padStart(2, '0');
        }
        
        updateCountdown();
        if (countdownInterval) clearInterval(countdownInterval);
        countdownInterval = setInterval(updateCountdown, 1000);
      }// ----------------------------------
      // レースグリッドのレンダリング
      // ----------------------------------
      function renderRaces() {
        const container = document.getElementById('race-grid-container');
        if (!container) return;
        container.innerHTML = '';
        
        const filtered = G1_RACES.filter(r => {
          const matchesFilter = currentFilter === 'all' || r.status === currentFilter;
          const matchesSearch = r.name.includes(searchQuery) || r.location.includes(searchQuery);
          return matchesFilter && matchesSearch;
        });
        
        updateTabCounts();
        
        if (filtered.length === 0) {
          container.innerHTML = `<div class="text-muted" style="grid-column: 1/-1; text-align: center; padding: 48px 0;">該当するレースが見つかりません。</div>`;
          return;
        }
        
        filtered.forEach(r => {
          const raceDate = new Date(r.date);
          const dateStr = `${raceDate.getMonth() + 1}/${raceDate.getDate()}`;
          const weekdayStr = ['日', '月', '火', '水', '木', '金', '土'][raceDate.getDay()];
          
          let locClass = '';
          if (r.location === '東京') locClass = 'loc-tokyo';
          else if (r.location === '中山') locClass = 'loc-nakayama';
          else if (r.location === '京都') locClass = 'loc-kyoto';
          else if (r.location === '阪神') locClass = 'loc-hanshin';
          else if (r.location === '中京') locClass = 'loc-chukyo';
          
          const card = document.createElement('div');
          card.className = `race-card ${locClass}`;
          card.setAttribute('data-id', r.id);
          
          let footerContent = '';
          const hasEntries = typeof ENTRIES_DATA !== 'undefined' && ENTRIES_DATA[r.id];

          if (r.status === 'finished') {
            footerContent = `
              <div class="card-result-preview">
                <div class="winner-row">
                  <svg class="winner-crown" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor"><path d="M2 4l3 5 7-6 7 6 3-5v14c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V4zm2 5.5l1.6-2.7 2.1 3.5 4.3-3.7 4.3 3.7 2.1-3.5L20 9.5V18H4V9.5z"/></svg>
                  <span class="winner-name">${r.winner}</span>
                  <span class="text-muted">(${r.winnerJockey})</span>
                </div>
                <div class="card-actions-group">
                  <button class="btn-card-action btn-card-result" onclick="event.stopPropagation(); openRaceDetail('${r.id}');">
                    <i data-lucide="trophy"></i>
                    <span>結果詳細</span>
                  </button>
                  <button class="btn-card-action btn-card-review" onclick="event.stopPropagation(); selectReviewRace('${r.id}'); switchView('review', true, true);">
                    <i data-lucide="file-text"></i>
                    <span>回顧・次走</span>
                  </button>
                </div>
              </div>
            `;
          } else {
            const stage = getRaceEntryStage(r.id);
            let stageBadge = '';
            if (stage === 'gate_confirmed') {
              stageBadge = '<span class="badge-stage-gates">枠順確定</span>';
            } else if (stage === 'starters_confirmed') {
              stageBadge = '<span class="badge-stage-confirmed">出走馬確定</span>';
            } else if (hasEntries) {
              stageBadge = '<span class="badge-stage-scheduled">出馬予定</span>';
            }
            footerContent = `
              <div class="card-result-preview">
                <div style="display:flex; justify-content:space-between; align-items:center; margin-top:6px;">
                  <span class="text-muted" style="font-size: 13px;">${stageBadge ? `<span style="margin-right: 6px;">${stageBadge}</span>` : ''}発走 15:40</span>
                  <div class="card-action-text">出馬表・詳細 <i data-lucide="arrow-right"></i></div>
                </div>
              </div>
            `;
          }

          card.innerHTML = `
            <div class="card-header-row">
              <span class="race-date-badge">${dateStr} (${weekdayStr})</span>
              <span class="race-status-badge ${r.status}">
                ${r.status === 'finished' ? '開催済' : '今後の予定'}
              </span>
            </div>
            <h3>${r.name}</h3>
            <div class="race-meta-info">
              <span>${r.location}競馬場</span>
              <span>|</span>
              <span>${r.course}</span>
            </div>
            <div class="race-card-footer">
              ${footerContent}
            </div>
          `;

          container.appendChild(card);
        });
        
        refreshIcons();
      }

      function updateTabCounts() {
        const allCount = G1_RACES.length;
        const finishedCount = G1_RACES.filter(r => r.status === 'finished').length;
        const upcomingCount = G1_RACES.filter(r => r.status === 'upcoming').length;
        
        const countAllEl = document.getElementById('count-all');
        const countFinishedEl = document.getElementById('count-finished');
        const countUpcomingEl = document.getElementById('count-upcoming');

        if (countAllEl) countAllEl.innerText = allCount;
        if (countFinishedEl) countFinishedEl.innerText = finishedCount;
        if (countUpcomingEl) countUpcomingEl.innerText = upcomingCount;
      }

      // ----------------------------------
      // レース結果補完エンジン（本物データ適用）
      // ----------------------------------
      function hydrateRaceResults(race) {
        if (race.hydratedResults) return race.hydratedResults;

        // 本物のデータベースに存在すればマッピング
        if (RESULTS_DATA[race.id]) {
          race.hydratedResults = RESULTS_DATA[race.id].map(mapArrayToResultObj);
          return race.hydratedResults;
        }

        // 以降はupcomingなどデータ未登録の場合の自動補完
        const totalStarters = 16;
        const results = [];
        const is3yo = race.type ? race.type.startsWith('3yo') : false;
        const isFemale = race.type ? race.type.endsWith('female') : false;
        
        let horsePool = is3yo ? (isFemale ? [...POOLS['3yo-female']] : [...POOLS['3yo-male']]) : [...POOLS['older']];
        horsePool = [...new Set(horsePool)].filter(h => h !== race.winner && h !== race.second && h !== race.third);

        let sexAgeLabel = is3yo ? (isFemale ? '牝3' : '牡3') : (isFemale ? '牝4' : '牡5');
        let jockeyLoad = is3yo ? (isFemale ? 55 : 57) : (isFemale ? 56 : 58);

        const baseSeconds = 120.0; // デフォルト基準

        // 1着
        results.push({
          rank: 1, gate: race.winnerGate || 1, horseName: race.winner || '勝ち馬', sexAge: sexAgeLabel,
          jockeyLoad, jockey: race.winnerJockey || 'J.騎手', time: race.time || '2:00.0', margin: '-',
          cornerSequence: '5-4-3-3', last3F: '34.2', odds: '3.5', popularity: 1,
          weight: '498', weightDiff: '+2', stable: STABLES_POOL[0]
        });

        // 2着
        results.push({
          rank: 2, gate: race.secondGate || 2, horseName: race.second || '2着馬', sexAge: sexAgeLabel,
          jockeyLoad, jockey: race.secondJockey || 'J.騎手', time: formatSecondsToTime(baseSeconds + 0.2), margin: '1馬身',
          cornerSequence: '7-6-5-4', last3F: '34.1', odds: '4.8', popularity: 2,
          weight: '488', weightDiff: '-2', stable: STABLES_POOL[1]
        });

        // 3着
        results.push({
          rank: 3, gate: race.thirdGate || 3, horseName: race.third || '3着馬', sexAge: sexAgeLabel,
          jockeyLoad, jockey: race.thirdJockey || 'J.騎手', time: formatSecondsToTime(baseSeconds + 0.4), margin: '1 1/4馬身',
          cornerSequence: '3-3-2-2', last3F: '34.5', odds: '6.5', popularity: 3,
          weight: '504', weightDiff: '+4', stable: STABLES_POOL[2]
        });

        let usedGates = new Set([race.winnerGate || 1, race.secondGate || 2, race.thirdGate || 3]);
        let currentSeconds = baseSeconds + 0.4;

        for (let r = 4; totalStarters >= r; r++) {
          const horseName = horsePool[r - 4] || `ダミーホース${r}`;
          const gate = getUniqueGate(usedGates, totalStarters);
          const jockey = JOCKEYS_POOL[r % JOCKEYS_POOL.length];
          
          const step = 0.2;
          currentSeconds += step;
          const time = formatSecondsToTime(currentSeconds);

          results.push({
            rank: r, gate: gate, horseName: horseName, sexAge: sexAgeLabel,
            jockeyLoad, jockey: jockey, time: time, margin: '1馬身',
            cornerSequence: '8-8-9-9', last3F: '35.0', odds: (10.0 + r * 5.0).toFixed(1), popularity: r,
            weight: '490', weightDiff: '0', stable: STABLES_POOL[r % STABLES_POOL.length]
          });
        }

        race.hydratedResults = results;
        return results;
      }

      function mapArrayToResultObj(arr) {
        return {
          rank: arr[0],
          gate: arr[1],
          horseName: arr[2],
          sexAge: arr[3],
          jockeyLoad: arr[4],
          jockey: arr[5],
          time: arr[6],
          margin: arr[7],
          cornerSequence: arr[8],
          last3F: arr[9],
          odds: arr[10],
          popularity: arr[11],
          weight: arr[12],
          weightDiff: arr[13],
          stable: arr[14]
        };
      }

      function getUniqueGate(usedGates, max) {
        let gate = Math.floor(Math.random() * max) + 1;
        while (usedGates.has(gate)) {
          gate = Math.floor(Math.random() * max) + 1;
        }
        usedGates.add(gate);
        return gate;
      }

      // ----------------------------------
      // NetKeiba本物 JRA 2026年 G1 払戻金データベース
      // ----------------------------------
      

function hydratePayouts(race) {
        if (race.hydratedPayouts) return race.hydratedPayouts;

        // 本物データベース PAYOUTS_DATA から完全に引っ張る
        if (PAYOUTS_DATA[race.id]) {
          race.hydratedPayouts = PAYOUTS_DATA[race.id];
          return race.hydratedPayouts;
        }

        // バックアップ用自動算出（upcomingなどの場合）
        const results = hydrateRaceResults(race);
        const r1 = results[0];
        const r2 = results[1];
        const r3 = results[2];

        const baseWin = race.payouts ? race.payouts.win : 500;
        const baseTrifecta = race.payouts ? race.payouts.trifecta : 5000;
        
        const winVal = baseWin;
        const place1 = Math.max(110, Math.floor(baseWin * 0.4));
        const place2 = Math.max(120, Math.floor(place1 * 1.3));
        const place3 = Math.max(130, Math.floor(place2 * 1.5));
        const winPop = 250 > baseWin ? 1 : 500 > baseWin ? 2 : 4;

        const placements = [
          { type: '単勝', comb: `${r1.gate}`, val: `¥${winVal.toLocaleString()}`, pop: `${winPop}` },
          { type: '複勝', comb: `${r1.gate}<br>${r2.gate}<br>${r3.gate}`, val: `¥${place1.toLocaleString()}<br>¥${place2.toLocaleString()}<br>¥${place3.toLocaleString()}`, pop: `1<br>2<br>3` },
          { type: '枠連', comb: '枠複', val: `¥${Math.floor(baseWin * 1.5).toLocaleString()}`, pop: `${winPop + 1}` },
          { type: '馬連', comb: `${Math.min(r1.gate, r2.gate)} - ${Math.max(r1.gate, r2.gate)}`, val: `¥${Math.floor(baseWin * 2.5).toLocaleString()}`, pop: `${winPop + 2}` },
          { type: '馬単', comb: `${r1.gate} → ${r2.gate}`, val: `¥${Math.floor(baseWin * 4.2).toLocaleString()}`, pop: `${winPop + 3}` },
          { type: 'ワイド', comb: `${Math.min(r1.gate, r2.gate)} - ${Math.max(r1.gate, r2.gate)}<br>${Math.min(r1.gate, r3.gate)} - ${Math.max(r1.gate, r3.gate)}<br>${Math.min(r2.gate, r3.gate)} - ${Math.max(r2.gate, r3.gate)}`, val: `¥${Math.floor(baseWin * 0.9).toLocaleString()}<br>¥${Math.floor(baseWin * 1.8).toLocaleString()}<br>¥${Math.floor(baseWin * 2.5).toLocaleString()}`, pop: `2<br>4<br>6` },
          { type: '三連複', comb: `${[r1.gate, r2.gate, r3.gate].sort((a,b)=>a-b).join(' - ')}`, val: `¥${baseTrifecta.toLocaleString()}`, pop: `${Math.floor(baseTrifecta / 350)}` },
          { type: '三連単', comb: `${r1.gate} → ${r2.gate} → ${r3.gate}`, val: `¥${Math.floor(baseTrifecta * 4.8).toLocaleString()}`, pop: `${Math.floor(baseTrifecta * 4.8 / 380)}` }
        ];

        race.hydratedPayouts = placements;
        return placements;
      }

      // ----------------------------------
      // レース展開（通過順）生成
      // ----------------------------------
      function getRacePaceSequence(race) {
        const results = hydrateRaceResults(race);
        const corners = [[], [], [], []];
        results.forEach(res => {
          const seq = res.cornerSequence.split('-');
          for (let i = 0; 4 > i; i++) {
            corners[i].push({ horse: res.gate, pos: Number(seq[i] || res.rank) });
          }
        });

        const output = [];
        for (let i = 0; 4 > i; i++) {
          corners[i].sort((a, b) => a.pos - b.pos);
          const seqStr = corners[i].map(c => c.horse).join('-');
          output.push({
            label: `${i + 1}コーナー`,
            sequence: seqStr
          });
        }
        return output;
      }

      function getWaku(gate, total) {
        if (8 >= total) return gate;
        if (total === 18) {
          if (2 >= gate) return 1;
          if (4 >= gate) return 2;
          if (6 >= gate) return 3;
          if (8 >= gate) return 4;
          if (10 >= gate) return 5;
          if (12 >= gate) return 6;
          if (15 >= gate) return 7;
          return 8;
        }
        if (total === 17) {
          if (2 >= gate) return 1;
          if (4 >= gate) return 2;
          if (6 >= gate) return 3;
          if (8 >= gate) return 4;
          if (10 >= gate) return 5;
          if (12 >= gate) return 6;
          if (14 >= gate) return 7;
          return 8;
        }
        if (total === 16) {
          if (2 >= gate) return 1;
          if (4 >= gate) return 2;
          if (6 >= gate) return 3;
          if (8 >= gate) return 4;
          if (10 >= gate) return 5;
          if (12 >= gate) return 6;
          if (14 >= gate) return 7;
          return 8;
        }
        if (total === 15) {
          if (2 >= gate) return 1;
          if (4 >= gate) return 2;
          if (6 >= gate) return 3;
          if (8 >= gate) return 4;
          if (10 >= gate) return 5;
          if (12 >= gate) return 6;
          if (13 >= gate) return 7;
          return 8;
        }
        return Math.min(8, Math.ceil(gate / 2));
      }

      // ----------------------------------
      // レース詳細モーダルの表示
      // ----------------------------------
      


      function formatSecondsToTime(seconds) {
        if (isNaN(seconds)) return '-';
        const m = Math.floor(seconds / 60);
        const s = (seconds % 60).toFixed(1);
        return m > 0 ? `${m}:${s.padStart(4, '0')}` : `${s}`;
      }



      function initEventListeners() {
        const tabBtns = document.querySelectorAll('.tab-btn');
        tabBtns.forEach(btn => {
          btn.addEventListener('click', () => {
            tabBtns.forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
            currentFilter = btn.getAttribute('data-filter');
            if (typeof localStorage !== 'undefined') {
              localStorage.setItem('keiba_calendar_filter', currentFilter);
            }
            renderRaces();
          });
        });

        const searchInput = document.getElementById('race-search');
        if (searchInput) {
          searchInput.addEventListener('input', (e) => {
            searchQuery = e.target.value;
            renderRaces();
          });
        }

        const gridContainer = document.getElementById('race-grid-container');
        if (gridContainer) {
          gridContainer.addEventListener('click', (e) => {
            const card = e.target.closest('.race-card');
            if (!card) return;
            const id = card.getAttribute('data-id');
            openRaceDetail(id);
          });
        }

        const modal = document.getElementById('modal-race-detail');
        if (modal) {
          const btnClose = document.getElementById('btn-close-modal');
          const backdrop = modal.querySelector('.modal-backdrop');
          
          if (btnClose) btnClose.addEventListener('click', closeModal);
          if (backdrop) backdrop.addEventListener('click', closeModal);
          modal.addEventListener('click', (e) => {
            if (e.target === modal || e.target.classList.contains('modal-backdrop')) {
              closeModal();
            }
          });
        }

        
        const modalHorse = document.getElementById('modal-horse-detail');
        if (modalHorse) {
          const btnCloseHorse = document.getElementById('btn-close-horse-modal');
          const backdropHorse = document.getElementById('backdrop-horse-detail');
          if (btnCloseHorse) btnCloseHorse.addEventListener('click', closeHorseModal);
          if (backdropHorse) backdropHorse.addEventListener('click', closeHorseModal);
          modalHorse.addEventListener('click', (e) => {
            if (e.target === modalHorse || e.target.classList.contains('modal-backdrop')) {
              closeHorseModal();
            }
          });
        }

        if (typeof window !== 'undefined') {
          window.addEventListener('keydown', (e) => {
            if (e.key === 'Escape') {
              closeModal();
              closeHorseModal();
              if (typeof closeMarkSheet === 'function') closeMarkSheet();
            }
          });
        }

        const navItems = document.querySelectorAll('.nav-item');
        navItems.forEach(n => {
          n.addEventListener('click', () => {
            const target = n.getAttribute('data-target');
            if (target === 'prediction') {
              navigateTo('#prediction-' + currentPredictionRaceId);
            } else if (target === 'review') {
              navigateTo('#review-' + currentReviewRaceId);
            } else {
              navigateTo('#calendar');
            }
          });
        });

        const heroBanner = document.getElementById('hero-countdown-banner');
        if (heroBanner) {
          heroBanner.addEventListener('click', (e) => {
            const nextR = (typeof getNextUpcomingRace === 'function') ? getNextUpcomingRace() : { id: '17' };
            if (e.target.closest('#btn-hero-detail')) {
              e.stopPropagation();
              openRaceDetail(nextR.id);
              return;
            }
            if (typeof setPredictionRace === 'function') setPredictionRace(nextR.id);
            navigateTo('#prediction-' + nextR.id);
          });
        }

        const btnHeroPred = document.getElementById('btn-hero-prediction');
        if (btnHeroPred) {
          btnHeroPred.addEventListener('click', (e) => {
            e.stopPropagation();
            const nextR = (typeof getNextUpcomingRace === 'function') ? getNextUpcomingRace() : { id: '17' };
            if (typeof setPredictionRace === 'function') setPredictionRace(nextR.id);
            navigateTo('#prediction-' + nextR.id);
          });
        }
      }



      // ----------------------------------------------------
      // 競走馬詳細プロファイルモーダル (netkeiba公式準拠・一体型)
      // ----------------------------------------------------
      function synthesizeHorseProfile(horseName) {
        let foundSexAge = '牡4歳';
        let foundJockey = '未定';
        let foundLoad = '58';
        let foundStable = 'JRA 厩舎';
        let foundOdds = '--';

        if (typeof PREDICTION_DATA !== 'undefined') {
          const rawStarters = (typeof getActivePredictionStarters === 'function') 
            ? getActivePredictionStarters() 
            : ((PREDICTION_DATA.starters) || []);
          const matched = rawStarters.find(s => s.horseName === horseName || horseName.includes(s.horseName) || s.horseName.includes(horseName));
          if (matched) {
            foundSexAge = matched.sexAge || foundSexAge;
            foundJockey = matched.jockey || foundJockey;
            foundLoad = matched.load || foundLoad;
            foundOdds = matched.odds || foundOdds;
            if (matched.stable) foundStable = matched.stable;
          }
        }

        return {
          name: horseName,
          englishName: horseName,
          sexAge: foundSexAge,
          color: 'サラブレッド',
          birthday: '-',
          owner: '-',
          breeder: '-',
          origin: '-',
          stable: foundStable,
          record: '-',
          earnings: '-',
          titles: [],
          photoUrl: null,
          pedigree: {},
          career: []
        };
      }

      function openHorseDetail(horseName) {
        if (!horseName) return;
        const modal = document.getElementById('modal-horse-detail');
        const title = document.getElementById('hd-modal-title');
        const subTitle = document.getElementById('hd-modal-subtitle');
        const body = document.getElementById('hd-modal-body');
        if (!modal || !body) return;

        let horse = null;
        if (typeof HORSE_DATABASE !== 'undefined' && HORSE_DATABASE) {
          horse = HORSE_DATABASE[horseName];
          if (!horse) {
            const cleanName = horseName.replace(/\s+/g, '');
            for (const k of Object.keys(HORSE_DATABASE)) {
              if (k.replace(/\s+/g, '') === cleanName) {
                horse = HORSE_DATABASE[k];
                break;
              }
            }
          }
        }

        if (!horse) {
          horse = synthesizeHorseProfile(horseName);
        }

        if (title) title.innerText = horse.name;
        if (subTitle) subTitle.innerText = horse.englishName ? `${horse.englishName.toUpperCase()} - netkeiba DATABASE` : 'HORSE DATABASE';

        // 主な勝鞍・タイトルバッジ
        let titlesHtml = '';
        if (horse.titles && horse.titles.length > 0) {
          titlesHtml = `
            <div style="margin-top: 10px; display: flex; flex-wrap: wrap; gap: 6px;">
              ${horse.titles.map(t => {
                let badgeClass = 'other';
                if (t.includes('GI') || t.includes('G1')) badgeClass = 'g1';
                else if (t.includes('GII') || t.includes('G2')) badgeClass = 'g2';
                else if (t.includes('GIII') || t.includes('G3')) badgeClass = 'g3';
                return `<span class="hd-title-badge ${badgeClass}">🏆 ${t}</span>`;
              }).join('')}
            </div>
          `;
        }

        // 血統データ
        const ped = horse.pedigree || {};

        // 全戦歴テーブル行 (career または races に対応)
        const careerList = horse.career || horse.races || [];
        let careerRowsHtml = '';
        if (careerList.length > 0) {
          careerRowsHtml = careerList.map((r, idx) => {
            let rRank = r.rank !== undefined ? r.rank : '-';
            let rClass = 'hd-rank-other';
            if (rRank === 1 || rRank === '1') rClass = 'hd-rank-1';
            else if (rRank === 2 || rRank === '2') rClass = 'hd-rank-2';
            else if (rRank === 3 || rRank === '3') rClass = 'hd-rank-3';

            let gradeBadge = '';
            if (r.race && (r.race.includes('(GI)') || r.race.includes('(G1)'))) gradeBadge = '<span style="background:#dc2626;color:#fff;font-size:10px;font-weight:800;padding:1px 4px;border-radius:3px;margin-right:4px;">G1</span>';
            else if (r.race && (r.race.includes('(GII)') || r.race.includes('(G2)'))) gradeBadge = '<span style="background:#7c3aed;color:#fff;font-size:10px;font-weight:800;padding:1px 4px;border-radius:3px;margin-right:4px;">G2</span>';
            else if (r.race && (r.race.includes('(GIII)') || r.race.includes('(G3)'))) gradeBadge = '<span style="background:#16a34a;color:#fff;font-size:10px;font-weight:800;padding:1px 4px;border-radius:3px;margin-right:4px;">G3</span>';
            else if (r.grade) gradeBadge = `<span style="background:#475569;color:#fff;font-size:10px;padding:1px 4px;border-radius:3px;margin-right:4px;">${r.grade}</span>`;

            const rTrack = r.track || r.condition || '良';
            const rStarters = r.starters || r.runners || '-';
            const rPop = r.pop ? `${r.pop}人` : '-';
            const rOdds = r.odds || '-';
            const rRival = r.rival || r.winnerRival || '-';

            return `
              <tr>
                <td style="color:#94a3b8;font-size:11px;">${r.date || '-'}</td>
                <td style="color:#cbd5e1;font-size:11px;">${r.venue || '-'}</td>
                <td style="color:#94a3b8;font-size:11px;">${r.weather || '-'}</td>
                <td style="color:#cbd5e1;font-size:11px;">${r.raceNum ? r.raceNum + 'R' : '-'}</td>
                <td style="text-align: left; font-weight: 700; color: #fff;">${gradeBadge}${r.race || '-'}</td>
                <td>${rStarters}</td>
                <td>${r.bracket || '-'}</td>
                <td>${r.gate || '-'}</td>
                <td style="color:#38bdf8;">${rOdds}</td>
                <td style="color:#94a3b8;">${rPop}</td>
                <td><span class="hd-rank-cell ${rClass}">${rRank}</span></td>
                <td style="color:#f1f5f9;font-weight:600;">${r.jockey || '-'}</td>
                <td>${r.load || '-'}</td>
                <td style="color:#cbd5e1;">${r.course || '-'}</td>
                <td>${rTrack}</td>
                <td style="font-weight:700;color:#fff;">${r.time || '-'}</td>
                <td style="color:#94a3b8;">${r.margin || '-'}</td>
                <td style="color:#94a3b8;font-size:11px;">${r.passing || '-'}</td>
                <td style="color:#94a3b8;font-size:11px;">${r.pace || '-'}</td>
                <td style="font-weight:800;color:#38bdf8;">${r.agari || '-'}</td>
                <td style="color:#cbd5e1;font-size:11px;">${r.weight || '-'}</td>
                <td style="text-align: left; color: #94a3b8; font-size: 11.5px;">${rRival}</td>
              </tr>
            `;
          }).join('');
        } else {
          careerRowsHtml = `<tr><td colspan="22" style="text-align: center; padding: 25px; color: #94a3b8;">戦歴データ集計中</td></tr>`;
        }

        body.innerHTML = `
          <!-- 1. トップ概要カード（写真 + netkeiba公式プロフィール） -->
          <div class="hd-top-card">
            <div class="hd-photo-wrapper ${!horse.photoUrl ? 'has-no-photo' : ''}">
              ${horse.photoUrl ? `
                <img src="${horse.photoUrl}" alt="${horse.name}" class="hd-photo" onerror="this.onerror=null; this.style.display='none'; this.parentElement.classList.add('has-no-photo'); const fb = this.parentElement.querySelector('.hd-no-photo-fallback'); if (fb) fb.style.display='flex';">
              ` : ''}
              <div class="hd-no-photo-fallback" style="${horse.photoUrl ? 'display: none;' : 'display: flex;'}">
                <div class="hd-no-photo-content">
                  <svg class="no-photo-camera-icon" xmlns="http://www.w3.org/2000/svg" width="38" height="38" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">
                    <path d="M14.5 4h-5L7 7H4a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-3l-2.5-3z"/>
                    <circle cx="12" cy="13" r="3"/>
                    <line x1="2" y1="2" x2="22" y2="22"/>
                  </svg>
                  <span class="no-photo-label">No Photo</span>
                  <span class="no-photo-sub">写真未登録</span>
                </div>
              </div>
              <span class="hd-photo-tag">${horse.color || 'サラブレッド'}</span>
            </div>
            <div>
              <div style="font-size: 24px; font-weight: 900; color: #fff; line-height: 1.2;">
                ${horse.name}
                <span style="font-size: 14px; font-weight: normal; color: #94a3b8; margin-left: 8px;">${horse.englishName || ''}</span>
              </div>
              <div style="font-size: 13.5px; color: #38bdf8; font-weight: 700; margin-top: 4px;">
                ${horse.sexAge || ''} / ${horse.color || ''}
              </div>

              <div class="hd-profile-grid" style="margin-top: 14px;">
                <div class="hd-profile-item">
                  <span class="hd-profile-label">生年月日</span>
                  <span class="hd-profile-val">${horse.birthday || '-'}</span>
                </div>
                <div class="hd-profile-item">
                  <span class="hd-profile-label">調教師</span>
                  <span class="hd-profile-val">${horse.stable || '-'}</span>
                </div>
                <div class="hd-profile-item">
                  <span class="hd-profile-label">馬主</span>
                  <span class="hd-profile-val">${horse.owner || '-'}</span>
                </div>
                <div class="hd-profile-item">
                  <span class="hd-profile-label">生産者 / 産地</span>
                  <span class="hd-profile-val">${horse.breeder || '-'}${horse.origin ? ` (${horse.origin})` : ''}</span>
                </div>
                <div class="hd-profile-item">
                  <span class="hd-profile-label">通算成績</span>
                  <span class="hd-profile-val" style="color: #fbbf24; font-weight: 800;">${horse.record || '-'}</span>
                </div>
                <div class="hd-profile-item">
                  <span class="hd-profile-label">獲得賞金 (中央)</span>
                  <span class="hd-profile-val" style="color: #34d399; font-weight: 800;">${horse.earnings || '-'}</span>
                </div>
                ${horse.price && horse.price !== '-' ? `
                <div class="hd-profile-item">
                  <span class="hd-profile-label">セリ取引価格</span>
                  <span class="hd-profile-val" style="color: #f1f5f9;">${horse.price}</span>
                </div>
                ` : ''}
              </div>

              ${titlesHtml}
            </div>
          </div>

          <!-- 2. 血統情報セクション（タブなし・縦並び表示） -->
          <div class="hd-section-box">
            <div class="hd-section-title">
              <span>🧬 血統情報 (Pedigree)</span>
            </div>
            <div class="hd-pedigree-grid">
              <!-- 父系 -->
              <div class="hd-pedigree-box" style="border-left: 3px solid #38bdf8;">
                <div class="hd-ped-title" style="color: #38bdf8;">父 (Sire)</div>
                <div class="hd-ped-name">${ped.sire || '-'}</div>
                <div class="hd-ped-sub">父父: ${ped.sireSire || '-'} / 父母: ${ped.sireDam || '-'}</div>
              </div>

              <!-- 母系 -->
              <div class="hd-pedigree-box" style="border-left: 3px solid #f43f5e;">
                <div class="hd-ped-title" style="color: #f43f5e;">母 (Dam)</div>
                <div class="hd-ped-name">${ped.dam || '-'}</div>
                <div class="hd-ped-sub">母父: ${ped.damSire || '-'} / 母母: ${ped.damDam || '-'}</div>
              </div>
            </div>

            <!-- クロスインブリード -->
            <div class="hd-cross-box">
              <span style="font-size: 11px; font-weight: 800; color: #fbbf24; margin-right: 8px;">🧬 5代インブリード（クロス）:</span>
              <span style="font-size: 12.5px; color: #f1f5f9; font-weight: 600;">${ped.crosses || '特になし (アウトブリード)'}</span>
            </div>
          </div>

          <!-- 3. 全競走成績・戦歴一覧セクション (全走書き出し・完全網羅) -->
          <div class="hd-section-box" style="margin-top: 24px;">
            <div class="hd-section-title">
              <span>📊 全競走成績・戦歴一覧 (全${careerList.length}走・デビュー戦〜直近レース)</span>
            </div>
            <div class="hd-career-table-wrapper">
              <table class="hd-career-table">
                <thead>
                  <tr>
                    <th>日付</th>
                    <th>開催</th>
                    <th>天</th>
                    <th>R</th>
                    <th>レース名</th>
                    <th>頭数</th>
                    <th>枠</th>
                    <th>馬番</th>
                    <th>オッズ</th>
                    <th>人気</th>
                    <th>着順</th>
                    <th>騎手</th>
                    <th>斤量</th>
                    <th>距離</th>
                    <th>馬場</th>
                    <th>タイム</th>
                    <th>着差</th>
                    <th>通過</th>
                    <th>ペース</th>
                    <th>上り</th>
                    <th>馬体重</th>
                    <th>勝ち馬 (2着馬)</th>
                  </tr>
                </thead>
                <tbody>
                  ${careerRowsHtml}
                </tbody>
              </table>
            </div>
          </div>
        `;

        modal.classList.add('open', 'active');
        document.body.style.overflow = 'hidden';
      }

      function closeHorseModal() {
        const modal = document.getElementById('modal-horse-detail');
        if (!modal) return;
        modal.classList.remove('open', 'active');
        document.body.style.overflow = '';
      }



      // ----------------------------------------------------
      // SPA Hash ルーティング ＆ ナビゲーション
      // ----------------------------------------------------
      let currentAppView = 'calendar';
      let lastMainView = 'calendar';
      let predictionSortType = 'gate';
      let activeSheetGate = null;
      let currentPredictionRaceId = '19'; // デフォルトは次走ジャパンカップ

      let oddsMode = 'estimated'; // 'estimated' または 'live'
      let oddsAutoRefreshTimer = null;
      let lastOddsRefreshTime = null;
      let liveOddsData = null;

      const MARK_CLASSES = {
        '◎': 'mark-honmei',
        '○': 'mark-taiko',
        '▲': 'mark-tanana',
        '△': 'mark-renka',
        '☆': 'mark-ana',
        '消': 'mark-keshi'
      };

      function refreshIcons() {
        if (typeof window !== 'undefined' && window.lucide && typeof window.lucide.createIcons === 'function') {
          window.lucide.createIcons();
        }
      }

      function scrollToSection(secId) {
        if (typeof document === 'undefined') return;
        if (secId === 'sec-memo') secId = 'pred-section-user-memo';
        const targetEl = document.getElementById(secId);
        if (targetEl) {
          targetEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
      }

      function navigateTo(routeHash) {
        if (typeof window === 'undefined') return;
        if (window.location.hash !== routeHash) {
          window.location.hash = routeHash;
        } else {
          handleRoute(false);
        }
      }

      function handleRoute(shouldScroll = false) {
        if (typeof window === 'undefined') return;

        let hash = window.location.hash || '';

        // If URL has lingering #sec- anchor, normalize so reload never jumps down to memo/sections
        if (hash.startsWith('#sec-')) {
          hash = '#prediction-' + (currentPredictionRaceId || '19');
          if (window.history && window.history.replaceState) {
            window.history.replaceState(null, '', hash);
          }
        }

        if (!hash || hash === '#' || hash === '#/') {
          if (typeof localStorage !== 'undefined') {
            const saved = localStorage.getItem('keiba_active_route');
            if (saved && !saved.startsWith('#sec-') && (saved.startsWith('#prediction') || saved.startsWith('#race-') || saved.startsWith('#review'))) {
              hash = saved;
              if (window.history && window.history.replaceState) {
                window.history.replaceState(null, '', hash);
              }
            } else {
              hash = '#calendar';
            }
          } else {
            hash = '#calendar';
          }
        }

        // Clean any saved #sec- in localStorage
        if (typeof localStorage !== 'undefined') {
          const saved = localStorage.getItem('keiba_active_route');
          if (saved && saved.startsWith('#sec-')) {
            localStorage.setItem('keiba_active_route', '#prediction-' + (currentPredictionRaceId || '19'));
          }
        }

        // 1. レース詳細モーダル ルート (#race-16, #race-17 など)
        if (hash.startsWith('#race-')) {
          const raceId = hash.replace('#race-', '');
          if (typeof localStorage !== 'undefined') {
            localStorage.setItem('keiba_active_route', hash);
          }
          const savedView = (typeof localStorage !== 'undefined') ? localStorage.getItem('keiba_last_main_view') : null;
          const baseView = ['prediction', 'review'].includes(savedView) ? savedView : 'calendar';
          switchView(baseView, false, false);
          openRaceDetail(raceId, false);
          return;
        }

        // 2. 予想ページ ルート (#prediction または #prediction-17 など)
        if (hash.startsWith('#prediction')) {
          closeModal();
          if (hash.startsWith('#prediction-')) {
            const targetId = hash.replace('#prediction-', '');
            if (typeof PREDICTION_DATA !== 'undefined' && PREDICTION_DATA.races && PREDICTION_DATA.races[targetId]) {
              currentPredictionRaceId = targetId;
            }
          }
          const cleanRoute = '#prediction-' + (currentPredictionRaceId || '19');
          if (typeof localStorage !== 'undefined') {
            localStorage.setItem('keiba_active_route', cleanRoute);
            localStorage.setItem('keiba_last_main_view', 'prediction');
          }
          switchView('prediction', shouldScroll, false);
          // リロード時や画面遷移時は常に最上部から表示（メモへ意図せずジャンプするのを完全に防止）
          if (typeof window !== 'undefined' && window.scrollTo) {
            window.scrollTo({ top: 0, behavior: 'instant' });
          }
          return;
        }

        // 2.5 レース回顧 ルート (#review または #review-17 など)
        if (hash.startsWith('#review')) {
          closeModal();
          if (hash.startsWith('#review-')) {
            const targetId = hash.replace('#review-', '');
            if (typeof RACE_REVIEWS_DATA !== 'undefined' && RACE_REVIEWS_DATA[targetId]) {
              currentReviewRaceId = targetId;
            }
          }
          if (typeof localStorage !== 'undefined') {
            localStorage.setItem('keiba_active_route', hash);
            localStorage.setItem('keiba_last_main_view', 'review');
          }
          switchView('review', shouldScroll, false);
          return;
        }

        // 3. カレンダー一覧 トップページ ルート (#calendar またはデフォルト)
        closeModal();
        if (typeof localStorage !== 'undefined') {
          localStorage.setItem('keiba_active_route', '#calendar');
          localStorage.setItem('keiba_last_main_view', 'calendar');
        }
        switchView('calendar', shouldScroll, false);
      }

      function switchView(viewName, shouldScroll = true, updateRoute = false) {
        if (updateRoute) {
          navigateTo('#' + viewName);
          return;
        }

        currentAppView = viewName;
        lastMainView = viewName;
        if (typeof localStorage !== 'undefined') {
          localStorage.setItem('keiba_last_main_view', viewName);
          localStorage.setItem('keiba_active_route', '#' + viewName);
        }

        const calView = document.getElementById('view-calendar');
        const predView = document.getElementById('view-prediction');
        const revView = document.getElementById('view-review');
        const navItems = document.querySelectorAll('.nav-item');

        if (viewName === 'prediction') {
          if (document.documentElement) {
            document.documentElement.classList.add('route-prediction');
            document.documentElement.classList.remove('route-calendar');
            document.documentElement.classList.remove('route-review');
          }
          if (calView) calView.style.display = 'none';
          if (predView) predView.style.display = 'block';
          if (revView) revView.style.display = 'none';
          navItems.forEach(n => {
            if (n.getAttribute('data-target') === 'prediction') n.classList.add('active');
            else n.classList.remove('active');
          });
          renderPredictionView();
          if (shouldScroll && typeof window !== 'undefined' && window.scrollTo) {
            window.scrollTo({ top: 0, behavior: 'instant' });
          }
        } else if (viewName === 'review') {
          if (document.documentElement) {
            document.documentElement.classList.add('route-review');
            document.documentElement.classList.remove('route-calendar');
            document.documentElement.classList.remove('route-prediction');
          }
          if (calView) calView.style.display = 'none';
          if (predView) predView.style.display = 'none';
          if (revView) revView.style.display = 'block';
          navItems.forEach(n => {
            if (n.getAttribute('data-target') === 'review') n.classList.add('active');
            else n.classList.remove('active');
          });
          renderReviewPills();
          renderReviewContent(currentReviewRaceId);
          if (shouldScroll && typeof window !== 'undefined' && window.scrollTo) {
            window.scrollTo({ top: 0, behavior: 'instant' });
          }
        } else {
          if (document.documentElement) {
            document.documentElement.classList.remove('route-prediction');
            document.documentElement.classList.remove('route-review');
            document.documentElement.classList.add('route-calendar');
          }
          if (calView) calView.style.display = 'block';
          if (predView) predView.style.display = 'none';
          if (revView) revView.style.display = 'none';
          navItems.forEach(n => {
            if (n.getAttribute('data-target') === 'calendar') n.classList.add('active');
            else n.classList.remove('active');
          });
          if (shouldScroll && typeof window !== 'undefined' && window.scrollTo) {
            window.scrollTo({ top: 0, behavior: 'instant' });
          }
        }
      }

      function closeModal() {
        const modal = document.getElementById('modal-race-detail');
        if (modal) {
          modal.classList.remove('open');
          modal.classList.remove('active');
        }
        document.body.style.overflow = '';
        if (typeof window !== 'undefined') {
          const baseRoute = (currentAppView === 'prediction') ? ('#prediction-' + currentPredictionRaceId) : '#calendar';
          if (window.location.hash.startsWith('#race-')) {
            if (window.history && window.history.replaceState) {
              window.history.replaceState(null, '', baseRoute);
            } else {
              window.location.hash = baseRoute;
            }
            if (typeof localStorage !== 'undefined') {
              localStorage.setItem('keiba_active_route', baseRoute);
            }
          }
        }
      }

      // 次回G1レースを自動判定（現在時刻から最も近い未終了レース）
      function getNextUpcomingRace() {
        const now = new Date();
        const upcoming = G1_RACES.filter(r => new Date(r.date) > now)
                                 .sort((a, b) => new Date(a.date) - new Date(b.date));
        return upcoming.length > 0 ? upcoming[0] : G1_RACES[G1_RACES.length - 1];
      }

      // 全自動ライフサイクル管理エンジン
      function autoLifecycleEngine() {
        const now = new Date();
        let changed = false;
        G1_RACES.forEach(r => {
          if (new Date(r.date) <= now && r.status !== 'finished') {
            r.status = 'finished';
            changed = true;
          }
        });
        if (changed) {
          renderRaces();
          updateTabCounts();
        }
        startNextRaceCountdown();
      }

      function isJraTicketSalesStarted(raceDateStr) {
        const now = new Date();
        if (!raceDateStr) return false;
        const raceDate = new Date(raceDateStr);
        const dayOfWeek = raceDate.getDay();
        const daysToFriday = (dayOfWeek === 0) ? 2 : (dayOfWeek === 6 ? 1 : 2);
        const salesStart = new Date(raceDate.getTime() - daysToFriday * 24 * 60 * 60 * 1000);
        salesStart.setHours(18, 30, 0, 0);
        return now >= salesStart;
      }

      function getTicketSalesStartTime(raceDateStr) {
        if (!raceDateStr) return '金曜 18:30';
        const raceDate = new Date(raceDateStr);
        const dayOfWeek = raceDate.getDay();
        const daysToFriday = (dayOfWeek === 0) ? 2 : (dayOfWeek === 6 ? 1 : 2);
        const salesStart = new Date(raceDate.getTime() - daysToFriday * 24 * 60 * 60 * 1000);
        salesStart.setHours(18, 30, 0, 0);
        const m = salesStart.getMonth() + 1;
        const d = salesStart.getDate();
        return `${m}/${d}(金) 18:30`;
      }

      function getActivePredictionStarters() {
        if (typeof PREDICTION_DATA !== 'undefined') {
          if (PREDICTION_DATA.races && PREDICTION_DATA.races[currentPredictionRaceId]) {
            return PREDICTION_DATA.races[currentPredictionRaceId].starters || [];
          }
          if (PREDICTION_DATA.starters) {
            return PREDICTION_DATA.starters;
          }
        }
        return [];
      }

      function initOddsState() {
        const raceObj = G1_RACES.find(r => r.id === currentPredictionRaceId);
        const isFinished = raceObj && raceObj.status === 'finished';

        if (isFinished) {
          oddsMode = 'live';
        } else if (typeof localStorage !== 'undefined') {
          const savedMode = localStorage.getItem('keiba_odds_mode_' + currentPredictionRaceId);
          if (savedMode === 'live' || savedMode === 'estimated') {
            oddsMode = savedMode;
          } else {
            oddsMode = isJraTicketSalesStarted(raceObj ? raceObj.date : null) ? 'live' : 'estimated';
          }
        } else {
          oddsMode = isJraTicketSalesStarted(raceObj ? raceObj.date : null) ? 'live' : 'estimated';
        }

        liveOddsData = null;
        if (typeof localStorage !== 'undefined') {
          try {
            const savedLive = localStorage.getItem('keiba_live_odds_' + currentPredictionRaceId);
            if (savedLive) liveOddsData = JSON.parse(savedLive);
          } catch(e) {}
        }

        if (!liveOddsData) {
          generateInitialLiveOdds();
        }
      }

      function generateInitialLiveOdds() {
        liveOddsData = {};
        const starters = getActivePredictionStarters();
        starters.forEach(s => {
          const baseWin = parseFloat(s.odds) || 10.0;
          liveOddsData[s.gate] = {
            win: baseWin,
            place: s.placeOdds || `${(baseWin * 0.35).toFixed(1)} - ${(baseWin * 0.55).toFixed(1)}`,
            pop: s.pop || 99
          };
        });
      }

      function refreshLiveOdds(simulateShift = true) {
        if (!liveOddsData || Object.keys(liveOddsData).length === 0) generateInitialLiveOdds();

        if (simulateShift) {
          const gates = Object.keys(liveOddsData);
          gates.forEach(g => {
            const currentWin = liveOddsData[g].win;
            let delta = 0;
            if (currentWin < 4.0) {
              delta = (Math.floor(Math.random() * 5) - 2) * 0.1;
            } else if (currentWin < 15.0) {
              delta = (Math.floor(Math.random() * 7) - 3) * 0.2;
            } else if (currentWin < 50.0) {
              delta = (Math.floor(Math.random() * 7) - 3) * 0.5;
            } else {
              delta = (Math.floor(Math.random() * 5) - 2) * 1.5;
            }
            let newWin = Math.max(1.1, +(currentWin + delta).toFixed(1));
            liveOddsData[g].win = newWin;
            
            const pMin = Math.max(1.1, +(newWin * 0.32).toFixed(1));
            const pMax = Math.max(pMin + 0.2, +(newWin * 0.52).toFixed(1));
            liveOddsData[g].place = `${pMin.toFixed(1)} - ${pMax.toFixed(1)}`;
          });

          // 単勝オッズ順に人気を自動再計算
          const sorted = gates.map(g => ({ gate: g, win: liveOddsData[g].win }))
                              .sort((a, b) => a.win - b.win);
          sorted.forEach((item, idx) => {
            liveOddsData[item.gate].pop = idx + 1;
          });

          if (typeof localStorage !== 'undefined') {
            localStorage.setItem('keiba_live_odds_' + currentPredictionRaceId, JSON.stringify(liveOddsData));
          }
        }

        const now = new Date();
        lastOddsRefreshTime = `${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}:${String(now.getSeconds()).padStart(2,'0')}`;
        renderNetkeibaHorseList();
        updateOddsControlUI();
        triggerOddsHighlight();
      }

      function setOddsMode(mode) {
        oddsMode = mode;
        if (typeof localStorage !== 'undefined') {
          localStorage.setItem('keiba_odds_mode_' + currentPredictionRaceId, mode);
        }
        if (mode === 'live' && (!liveOddsData || Object.keys(liveOddsData).length === 0)) {
          generateInitialLiveOdds();
        }
        renderNetkeibaHorseList();
        updateOddsControlUI();
      }

      function updateOddsControlUI() {
        if (typeof document === 'undefined') return;
        const btnEstimated = document.getElementById('btn-odds-estimated');
        const btnLive = document.getElementById('btn-odds-live');
        const badge = document.getElementById('odds-mode-badge');
        const badgeText = document.getElementById('odds-mode-text');
        const countdown = document.getElementById('odds-sales-countdown');
        const timeEl = document.getElementById('odds-update-time');
        const oddsCard = document.querySelector('.odds-control-card');

        const raceObj = G1_RACES.find(r => r.id === currentPredictionRaceId);
        const isFinished = raceObj && raceObj.status === 'finished';

        if (isFinished) {
          if (oddsCard) oddsCard.style.display = 'none';
          return;
        } else {
          if (oddsCard) oddsCard.style.display = 'block';
        }

        if (btnEstimated && btnLive) {
          if (oddsMode === 'estimated') {
            btnEstimated.classList.add('active');
            btnLive.classList.remove('active');
          } else {
            btnEstimated.classList.remove('active');
            btnLive.classList.add('active');
          }
        }

        const salesTimeStr = getTicketSalesStartTime(raceObj ? raceObj.date : null);

        if (badge && badgeText) {
          if (oddsMode === 'estimated') {
            badge.className = 'odds-mode-badge pre-sale';
            badgeText.innerText = '想定予想オッズ (netkeiba参考)';
            if (countdown) {
              countdown.innerText = `※${salesTimeStr}夜間発売開始とともに確定オッズへ自動切替`;
            }
          } else {
            badge.className = 'odds-mode-badge live-sale';
            badgeText.innerText = '● 発売中・リアルタイムオッズ (30秒自動更新)';
            if (countdown) {
              countdown.innerText = '※JRA公式発売オッズ連動シミュレーション中';
            }
          }
        }

        if (timeEl) {
          if (lastOddsRefreshTime) {
            timeEl.innerText = `● ${lastOddsRefreshTime} 自動更新済`;
          } else {
            timeEl.innerText = '● リアルタイム';
          }
        }
      }

      function startOddsAutoRefresh() {
        if (oddsAutoRefreshTimer) clearInterval(oddsAutoRefreshTimer);
        oddsAutoRefreshTimer = setInterval(() => {
          const currentView = document.querySelector('.app-view:not([style*="display: none"])');
          if (currentView && currentView.id === 'view-prediction') {
            const raceObj = G1_RACES.find(r => r.id === currentPredictionRaceId);
            if (raceObj && raceObj.status !== 'finished') {
              if (oddsMode === 'live') {
                refreshLiveOdds(true);
              } else {
                if (isJraTicketSalesStarted(raceObj.date)) {
                  setOddsMode('live');
                }
              }
            }
          }
        }, 30000);
      }

      function triggerOddsHighlight() {
        const oddsCells = document.querySelectorAll('.nh-odds-val');
        oddsCells.forEach(c => {
          c.style.transition = 'color 0.3s ease, transform 0.3s ease';
          c.style.color = 'var(--gold)';
          c.style.transform = 'scale(1.08)';
          setTimeout(() => {
            c.style.color = '';
            c.style.transform = '';
          }, 800);
        });
      }

      function initWeightState() {}
      function updateWeightControlUI() {}

      function getUserMarks() {
        if (typeof localStorage === 'undefined') return {};
        try {
          return JSON.parse(localStorage.getItem('keiba_marks_' + currentPredictionRaceId)) || {};
        } catch(e) {
          return {};
        }
      }

      function setUserMark(gate, mark) {
        const marks = getUserMarks();
        if (mark === '未' || !mark) {
          delete marks[gate];
        } else {
          marks[gate] = mark;
        }
        if (typeof localStorage !== 'undefined') {
          localStorage.setItem('keiba_marks_' + currentPredictionRaceId, JSON.stringify(marks));
        }
        updateMarksUI();
      }

      function updateMarksUI() {
        const marks = getUserMarks();
        const starters = getActivePredictionStarters();

        document.querySelectorAll('.nh-mark-btn').forEach(btn => {
          const g = btn.getAttribute('data-gate');
          const m = marks[g] || '';
          btn.innerText = m;
          btn.className = `nh-mark-btn ${MARK_CLASSES[m] || ''}`;
        });

        // Contender Ranking 内の印ボタンのアクティブ状態をリアルタイム同期
        document.querySelectorAll('.btn-drawer-mark').forEach(btn => {
          const g = btn.getAttribute('data-gate');
          const m = btn.getAttribute('data-mark');
          const activeMark = marks[g] || '';
          if (m && m === activeMark) {
            btn.classList.add('active');
          } else {
            btn.classList.remove('active');
          }
        });

        // Contender Ranking 行内の割当印バッジを同期
        document.querySelectorAll('.ranking-assigned-mark-badge').forEach(badge => {
          const g = badge.getAttribute('data-gate');
          const activeMark = marks[g] || '';
          badge.innerText = activeMark;
          badge.style.display = activeMark ? 'inline-flex' : 'none';
          badge.className = `ranking-assigned-mark-badge ${MARK_CLASSES[activeMark] || ''}`;
        });

        const markTypes = [
          { mark: '◎', id: 'summary-mark-honmei' },
          { mark: '○', id: 'summary-mark-taiko' },
          { mark: '▲', id: 'summary-mark-tanana' },
          { mark: '△', id: 'summary-mark-renka' },
          { mark: '☆', id: 'summary-mark-ana' }
        ];

        markTypes.forEach(mt => {
          const el = document.getElementById(mt.id);
          if (!el) return;
          const assignedGates = Object.keys(marks).filter(g => marks[g] === mt.mark);
          if (assignedGates.length > 0) {
            const stage = getRaceEntryStage(currentPredictionRaceId);
            const isGateConfirmed = (stage === 'gate_confirmed');
            const horseNames = assignedGates.map(g => {
              const h = starters.find(s => String(s.gate) === String(g) || s.horseName === g || s.horseName.replace(/\s+/g, '') === g);
              if (h) {
                return (isGateConfirmed && h.gate) ? `${h.gate}.${h.horseName}` : h.horseName;
              }
              return `${g}番`;
            });
            el.innerText = horseNames.join(', ');
            el.classList.add('has-assigned');
          } else {
            el.innerText = '未選択';
            el.classList.remove('has-assigned');
          }
        });
      }

      function openMarkSheet(gate) {
        activeSheetGate = gate;
        const starters = getActivePredictionStarters();
        const horse = starters.find(s => String(s.gate) === String(gate) || s.horseName === gate || s.horseName.replace(/\s+/g, '') === gate);
        if (!horse) return;

        const sheet = document.getElementById('mark-bottom-sheet');
        const backdrop = document.getElementById('mark-sheet-backdrop');
        const gateBadge = document.getElementById('sheet-target-gate');
        const nameEl = document.getElementById('sheet-target-name');

        const stage = getRaceEntryStage(currentPredictionRaceId);
        const isGateConfirmed = (stage === 'gate_confirmed');

        if (gateBadge) {
          if (isGateConfirmed && horse.gate) {
            gateBadge.className = `nh-gate-cell waku-${horse.waku || 1}`;
            gateBadge.innerText = horse.gate;
          } else {
            gateBadge.className = 'nh-gate-cell unconfirmed';
            gateBadge.innerText = '-';
          }
        }

        if (gateBadge) {
          gateBadge.className = `nh-gate-cell waku-${horse.waku}`;
          gateBadge.innerText = horse.gate;
        }
        if (nameEl) {
          nameEl.innerText = `${horse.horseName} (${horse.jockey})`;
        }

        const currentMark = getUserMarks()[gate] || '';
        document.querySelectorAll('.btn-sheet-mark').forEach(btn => {
          if (btn.getAttribute('data-mark') === currentMark) {
            btn.classList.add('selected');
          } else {
            btn.classList.remove('selected');
          }
        });

        if (sheet && backdrop) {
          sheet.classList.add('open', 'active');
          backdrop.classList.add('open', 'active');
        }
      }

      function closeMarkSheet() {
        const sheet = document.getElementById('mark-bottom-sheet');
        const backdrop = document.getElementById('mark-sheet-backdrop');
        if (sheet && backdrop) {
          sheet.classList.remove('open', 'active');
          backdrop.classList.remove('open', 'active');
        }
        activeSheetGate = null;
      }

