      let currentRankingSort = 'composite';

      function renderContenderRanking() {
        if (typeof document === 'undefined') return;
        const container = document.getElementById('pred-ranking-container');
        if (!container) return;

        const raceObj = (typeof G1_RACES !== 'undefined') ? G1_RACES.find(r => r.id === currentPredictionRaceId) : null;
        const raceNameDisp = raceObj ? raceObj.name : 'G1';
        const raceLocDisp = raceObj ? `${raceObj.location}コース` : 'コース';
        const raceCourseDisp = raceObj ? raceObj.course : '距離';

        const currentPred = (PREDICTION_DATA.races && PREDICTION_DATA.races[currentPredictionRaceId]) 
          ? PREDICTION_DATA.races[currentPredictionRaceId] 
          : PREDICTION_DATA;

        const rawList = currentPred.contenderRanking;
        if (!rawList || rawList.length === 0) {
          container.innerHTML = '';
          return;
        }

        // Normalize item fields safely with fallbacks
        let list = rawList.map((item, idx) => {
          const sc = item.scores || item.factors || {};
          const trainingScore = sc.training || sc.workout || 80;
          const jockeyScore = sc.jockey || 80;
          const courseScore = sc.course || 80;
          const distanceScore = sc.distance || 80;
          const prevRaceScore = sc.prevRace || sc.lastRace || 80;
          const pedigreeScore = sc.pedigree || 80;
          const compScore = item.compositeScore || item.totalScore || 80;
          const rankVal = item.rank || (idx + 1);
          const defaultMark = rankVal === 1 ? '◎' : (rankVal === 2 ? '○' : (rankVal === 3 ? '▲' : (rankVal <= 5 ? '△' : (rankVal === 6 ? '☆' : ''))));

          return {
            ...item,
            rank: rankVal,
            compositeScore: compScore,
            scores: {
              training: trainingScore,
              jockey: jockeyScore,
              course: courseScore,
              distance: distanceScore,
              prevRace: prevRaceScore,
              pedigree: pedigreeScore
            },
            strengths: item.strengths || item.comment || '-',
            concerns: item.concerns || '-',
            grade: item.grade || (compScore >= 95 ? 'SS' : (compScore >= 90 ? 'S' : (compScore >= 80 ? 'A' : (compScore >= 70 ? 'B' : 'C')))),
            gradeTag: item.gradeTag || (rankVal === 1 ? '本命最有力' : (rankVal === 2 ? '対抗筆頭' : (rankVal === 3 ? '単穴警戒' : (rankVal <= 5 ? '連下候補' : '大穴警戒')))),
            recommendedMark: item.recommendedMark || defaultMark
          };
        });

        if (currentRankingSort === 'training') {
          list.sort((a, b) => b.scores.training - a.scores.training);
        } else if (currentRankingSort === 'aptitude') {
          list.sort((a, b) => (b.scores.course + b.scores.distance) - (a.scores.course + a.scores.distance));
        } else if (currentRankingSort === 'value') {
          list.sort((a, b) => {
            const valA = a.compositeScore / (parseFloat(a.odds) || 10);
            const valB = b.compositeScore / (parseFloat(b.odds) || 10);
            return valB - valA;
          });
        } else {
          list.sort((a, b) => b.compositeScore - a.compositeScore);
        }

        const hasGateConfirmed = list.some(h => h.gate != null && h.waku != null);
        const hasWeightConfirmed = list.some(h => h.confirmedWeight != null || (h.weightDiff != null && h.weightDiff !== ''));

        const top3 = list.slice(0, 3);
        const rest = list.slice(3);
        const userMarks = getUserMarks();

        const podiumCardsHtml = top3.map((h, idx) => {
          const rankNum = idx + 1;
          const rankTag = rankNum === 1 ? '👑 1位 本命' : (rankNum === 2 ? '🥈 2位 対抗' : '🥉 3位 単穴');
          const rankClass = `rank-${rankNum}`;
          const gateDisp = (h.gate != null) ? h.gate : '-';
          const wakuClass = (h.waku != null) ? `waku-${h.waku}` : 'waku-unconfirmed';
          const gateKey = (h.gate != null) ? String(h.gate) : h.horseName;
          const currentMark = userMarks[gateKey] || '';
          
          return `
            <div class="podium-card ${rankClass}">
              <div class="podium-badge-row">
                <span class="podium-rank-tag">${rankTag}</span>
                <div class="podium-score-tag">期待度: <span>${h.compositeScore}</span>点</div>
              </div>
              <div class="podium-horse-header">
                <span class="podium-gate-box ${wakuClass}">${gateDisp}</span>
                <span class="podium-horse-name" onclick="openHorseDetail('${h.horseName}');" title="競走馬詳細を見る">
                  ${h.horseName}
                </span>
                <span class="podium-grade-pill">${h.grade} ${h.gradeTag}</span>
                ${currentMark ? `<span class="ranking-assigned-mark-badge ${MARK_CLASSES[currentMark] || ''}" data-gate="${gateKey}">${currentMark}</span>` : `<span class="ranking-assigned-mark-badge" data-gate="${gateKey}" style="display:none;"></span>`}
              </div>
              <div class="podium-subinfo">
                <span>${h.sexAge} ${h.load}kg</span> / 
                <span style="color: #38bdf8; font-weight: 600;">${h.jockey}</span> / 
                <span>${h.stable}</span>
              </div>

              <!-- 6大ファクター スコアメーター -->
              <div class="factor-meters">
                <div class="meter-item">
                  <div class="meter-header"><span>🏃 調教状態</span><strong>${h.scores.training}点</strong></div>
                  <div class="meter-track"><div class="meter-fill" style="width: ${h.scores.training}%;"></div></div>
                </div>
                <div class="meter-item">
                  <div class="meter-header"><span>🏇 鞍上力</span><strong>${h.scores.jockey}点</strong></div>
                  <div class="meter-track"><div class="meter-fill" style="width: ${h.scores.jockey}%;"></div></div>
                </div>
                <div class="meter-item">
                  <div class="meter-header"><span>🏟️ コース適性</span><strong>${h.scores.course}点</strong></div>
                  <div class="meter-track"><div class="meter-fill" style="width: ${h.scores.course}%;"></div></div>
                </div>
                <div class="meter-item">
                  <div class="meter-header"><span>⚡ 距離適性</span><strong>${h.scores.distance}点</strong></div>
                  <div class="meter-track"><div class="meter-fill" style="width: ${h.scores.distance}%;"></div></div>
                </div>
                <div class="meter-item">
                  <div class="meter-header"><span>📊 前走評価</span><strong>${h.scores.prevRace}点</strong></div>
                  <div class="meter-track"><div class="meter-fill" style="width: ${h.scores.prevRace}%;"></div></div>
                </div>
                <div class="meter-item">
                  <div class="meter-header"><span>🧬 血統適性</span><strong>${h.scores.pedigree}点</strong></div>
                  <div class="meter-track"><div class="meter-fill" style="width: ${h.scores.pedigree}%;"></div></div>
                </div>
              </div>

              <div class="podium-analysis-box">
                ${h.strengths}
              </div>

              <div class="podium-concerns-box">
                ⚠️ 唯一の懸念: ${h.concerns}
              </div>

              <div class="podium-actions">
                <div class="drawer-marks-group" style="margin-bottom: 8px;">
                  <span class="drawer-marks-label">予想印:</span>
                  <button class="btn-drawer-mark mark-honmei ${currentMark === '◎' ? 'active' : ''}" data-gate="${gateKey}" data-mark="◎" onclick="event.stopPropagation(); setUserMark('${gateKey}', '◎');">◎ 本命</button>
                  <button class="btn-drawer-mark mark-taiko ${currentMark === '○' ? 'active' : ''}" data-gate="${gateKey}" data-mark="○" onclick="event.stopPropagation(); setUserMark('${gateKey}', '○');">○ 対抗</button>
                  <button class="btn-drawer-mark mark-tanana ${currentMark === '▲' ? 'active' : ''}" data-gate="${gateKey}" data-mark="▲" onclick="event.stopPropagation(); setUserMark('${gateKey}', '▲');">▲ 単穴</button>
                  <button class="btn-drawer-mark mark-renka ${currentMark === '△' ? 'active' : ''}" data-gate="${gateKey}" data-mark="△" onclick="event.stopPropagation(); setUserMark('${gateKey}', '△');">△ 連下</button>
                  <button class="btn-drawer-mark mark-ana ${currentMark === '☆' ? 'active' : ''}" data-gate="${gateKey}" data-mark="☆" onclick="event.stopPropagation(); setUserMark('${gateKey}', '☆');">☆ 穴</button>
                  <button class="btn-drawer-mark mark-clear" data-gate="${gateKey}" data-mark="" onclick="event.stopPropagation(); setUserMark('${gateKey}', '');">消</button>
                </div>
                <button class="btn-detail-link" onclick="openHorseDetail('${h.horseName}');">
                  📖 競走馬詳細 (血統・戦歴・写真)
                </button>
              </div>
            </div>
          `;
        }).join('');

        const restRowsHtml = rest.map((h, idx) => {
          const rankNum = idx + 4;
          const gateDisp = (h.gate != null) ? h.gate : '-';
          const wakuClass = (h.waku != null) ? `waku-${h.waku}` : 'waku-unconfirmed';
          const gateKey = (h.gate != null) ? String(h.gate) : h.horseName;
          const currentMark = userMarks[gateKey] || '';
          const rowId = (h.gate != null) ? String(h.gate) : `h-${idx}`;
          return `
            <div class="ranking-row-wrapper" id="ranking-wrapper-${rowId}">
              <div class="ranking-row-item" onclick="toggleRankingRowDetail('${rowId}');" title="クリックして詳細評価を展開/閉じる">
                <span class="ranking-pos-badge">${rankNum}</span>
                <span class="podium-gate-box ${wakuClass}" style="width: 24px; height: 24px; font-size: 11px; border-radius: 4px; flex-shrink: 0;">${gateDisp}</span>
                <div class="ranking-row-main">
                  <div class="ranking-row-title">
                    <span class="ranking-row-name" onclick="event.stopPropagation(); openHorseDetail('${h.horseName}');" title="クリックして競走馬詳細（血統・戦歴・写真）を見る">
                      ${h.horseName}
                    </span>
                    <span class="ranking-row-jockey">${h.jockey} (${h.load}kg)</span>
                    <span class="podium-grade-pill" style="font-size: 9.5px; padding: 1px 6px;">${h.grade} ${h.gradeTag}</span>
                    ${currentMark ? `<span class="ranking-assigned-mark-badge ${MARK_CLASSES[currentMark] || ''}" data-gate="${gateKey}">${currentMark}</span>` : `<span class="ranking-assigned-mark-badge" data-gate="${gateKey}" style="display:none;"></span>`}
                  </div>
                  <div class="ranking-row-comment" title="${h.strengths}">
                    ${h.strengths}
                  </div>
                </div>
                <div class="ranking-row-score">
                  <div class="ranking-score-val">${h.compositeScore}<span style="font-size: 10px; font-weight: normal; color: var(--text-muted); margin-left: 2px;">点</span></div>
                  <div class="ranking-grade-tag">調教${h.scores.training}/鞍上${h.scores.jockey}</div>
                </div>
                <button class="btn-ranking-toggle" id="ranking-toggle-btn-${rowId}" onclick="event.stopPropagation(); toggleRankingRowDetail('${rowId}');" aria-label="詳細展開/閉じる">
                  <span id="ranking-toggle-text-${rowId}">詳細</span>
                  <span id="ranking-arrow-${rowId}" class="ranking-toggle-arrow">▾</span>
                </button>
              </div>

              <!-- クリックで開閉する詳細アコーディオン -->
              <div class="ranking-row-drawer" id="ranking-drawer-${rowId}" style="display: none;">
                <div class="ranking-drawer-inner">
                  <div class="drawer-factor-title">
                    <span>⚡ 6大ファクター個別評価スコア</span>
                    <span style="font-size: 11.5px; color: var(--text-muted);">
                      ${h.sexAge} / ${h.stable} / 想定${h.odds}倍 (${h.pop}番人気) / AI推奨印: <strong style="color: var(--gold);">${h.recommendedMark}</strong>
                    </span>
                  </div>

                  <!-- 6大ファクター メーター -->
                  <div class="factor-meters">
                    <div class="meter-item">
                      <div class="meter-header"><span>🏃 調教状態</span><strong>${h.scores.training}点</strong></div>
                      <div class="meter-track"><div class="meter-fill" style="width: ${h.scores.training}%;"></div></div>
                    </div>
                    <div class="meter-item">
                      <div class="meter-header"><span>🏇 鞍上力</span><strong>${h.scores.jockey}点</strong></div>
                      <div class="meter-track"><div class="meter-fill" style="width: ${h.scores.jockey}%;"></div></div>
                    </div>
                    <div class="meter-item">
                      <div class="meter-header"><span>🏟️ コース適性</span><strong>${h.scores.course}点</strong></div>
                      <div class="meter-track"><div class="meter-fill" style="width: ${h.scores.course}%;"></div></div>
                    </div>
                    <div class="meter-item">
                      <div class="meter-header"><span>⚡ 距離適性</span><strong>${h.scores.distance}点</strong></div>
                      <div class="meter-track"><div class="meter-fill" style="width: ${h.scores.distance}%;"></div></div>
                    </div>
                    <div class="meter-item">
                      <div class="meter-header"><span>📊 前走評価</span><strong>${h.scores.prevRace}点</strong></div>
                      <div class="meter-track"><div class="meter-fill" style="width: ${h.scores.prevRace}%;"></div></div>
                    </div>
                    <div class="meter-item">
                      <div class="meter-header"><span>🧬 血統適性</span><strong>${h.scores.pedigree}点</strong></div>
                      <div class="meter-track"><div class="meter-fill" style="width: ${h.scores.pedigree}%;"></div></div>
                    </div>
                  </div>

                  <!-- 分析ボックス: 好走要因 & 懸念 -->
                  <div class="drawer-analysis-grid">
                    <div class="drawer-analysis-box">
                      <div class="drawer-box-label">🎯 好走要因・推奨根拠</div>
                      <div class="drawer-box-text">${h.strengths}</div>
                    </div>
                    <div class="drawer-concerns-box">
                      <div class="drawer-box-label">⚠️ 懸念材料・死角</div>
                      <div class="drawer-box-text">${h.concerns}</div>
                    </div>
                  </div>

                  <!-- 下部アクションバー: 印割当 & 競走馬詳細リンク -->
                  <div class="drawer-action-bar">
                    <div class="drawer-marks-group">
                      <span class="drawer-marks-label">予想印割当:</span>
                      <button class="btn-drawer-mark mark-honmei ${currentMark === '◎' ? 'active' : ''}" data-gate="${gateKey}" data-mark="◎" onclick="event.stopPropagation(); setUserMark('${gateKey}', '◎');">◎ 本命</button>
                      <button class="btn-drawer-mark mark-taiko ${currentMark === '○' ? 'active' : ''}" data-gate="${gateKey}" data-mark="○" onclick="event.stopPropagation(); setUserMark('${gateKey}', '○');">○ 対抗</button>
                      <button class="btn-drawer-mark mark-tanana ${currentMark === '▲' ? 'active' : ''}" data-gate="${gateKey}" data-mark="▲" onclick="event.stopPropagation(); setUserMark('${gateKey}', '▲');">▲ 単穴</button>
                      <button class="btn-drawer-mark mark-renka ${currentMark === '△' ? 'active' : ''}" data-gate="${gateKey}" data-mark="△" onclick="event.stopPropagation(); setUserMark('${gateKey}', '△');">△ 連下</button>
                      <button class="btn-drawer-mark mark-ana ${currentMark === '☆' ? 'active' : ''}" data-gate="${gateKey}" data-mark="☆" onclick="event.stopPropagation(); setUserMark('${gateKey}', '☆');">☆ 穴</button>
                      <button class="btn-drawer-mark mark-clear" data-gate="${gateKey}" data-mark="" onclick="event.stopPropagation(); setUserMark('${gateKey}', '');">クリア</button>
                    </div>

                    <button class="btn-detail-link" onclick="event.stopPropagation(); openHorseDetail('${h.horseName}');" title="netkeiba準拠 競走馬詳細（血統・全戦歴・写真）を見る">
                      📖 競走馬詳細（血統・戦歴）
                    </button>
                  </div>
                </div>
              </div>
            </div>
          `;
        }).join('');

        container.innerHTML = `
          <div class="pred-ranking-card">
            <div class="ranking-top-bar">
              <div class="ranking-title-group">
                <div style="display: flex; align-items: center; gap: 6px;">
                  <span style="font-size: 11px; font-weight: 700; color: var(--gold); background: rgba(245, 158, 11, 0.15); border: 1px solid rgba(245, 158, 11, 0.3); padding: 2px 8px; border-radius: 4px;">AI×データ多変量解析</span>
                  <span style="font-size: 11px; color: var(--text-muted);">全18頭 徹底スコアリング</span>
                </div>
                <h2>🏆 ${raceNameDisp} 好走期待度ランキング</h2>
                <div class="ranking-subtitle">
                  調教状態 (20%) ・ 鞍上力 (20%) ・ ${raceLocDisp}適性 (15%) ・ ${raceCourseDisp}適性 (15%) ・ 前走評価 (15%) ・ 血統背景 (15%)
                </div>
              </div>

              <div class="ranking-actions">
                <div class="ranking-sort-group">
                  <button class="btn-ranking-sort ${currentRankingSort === 'composite' ? 'active' : ''}" onclick="setRankingSort('composite')">総合期待度</button>
                  <button class="btn-ranking-sort ${currentRankingSort === 'training' ? 'active' : ''}" onclick="setRankingSort('training')">調教重視</button>
                  <button class="btn-ranking-sort ${currentRankingSort === 'aptitude' ? 'active' : ''}" onclick="setRankingSort('aptitude')">適性重視</button>
                  <button class="btn-ranking-sort ${currentRankingSort === 'value' ? 'active' : ''}" onclick="setRankingSort('value')">妙味・穴馬</button>
                </div>
                <button class="btn-apply-marks" onclick="applyRankingToMarks();" title="上位6頭を予想印(◎○▲△☆)に自動設定">
                  <i data-lucide="zap" style="width: 13px; height: 13px;"></i> 上位印に自動反映
                </button>
              </div>
            </div>

            <!-- 調教・枠順・確定馬体重 連動自動更新ステータス -->
            <div class="factor-sync-row">
              <span class="factor-sync-badge auto-recalc"><span class="pulse-dot"></span> 調教・枠・馬体重 連動自動更新中</span>
              <span class="factor-sync-badge ${hasGateConfirmed ? 'confirmed' : 'pending'}">
                ${hasGateConfirmed ? '⚡ 枠順確定（内外枠バイアス適用済）' : '⏳ 枠順発表前（確定時に内外枠バイアス即時反映）'}
              </span>
              <span class="factor-sync-badge ${hasWeightConfirmed ? 'confirmed' : 'pending'}">
                ${hasWeightConfirmed ? '⚖️ 確定馬体重（増減仕上がり補正適用済）' : '⏳ 当日馬体重発表前（発表時に増減補正即時反映）'}
              </span>
              <span class="factor-sync-badge confirmed">
                🏃 最終追切・調教評価反映済
              </span>
            </div>

            <!-- 表彰台 TOP3 ポディウムカード -->
            <div class="podium-grid">
              ${podiumCardsHtml}
            </div>

            <!-- 4位〜18位 テーブルリスト -->
            <div class="ranking-table-container">
              <div class="ranking-table-header">
                <div style="display: flex; align-items: center; gap: 8px;">
                  <span>4位〜18位 好走期待度一覧（クリックで詳細閲覧）</span>
                  <button class="btn-ranking-toggle-all" onclick="toggleAllRankingDrawers();" id="btn-toggle-all-ranking">全て展開 ▾</button>
                </div>
                <span style="font-size: 11px; color: var(--text-muted);">総合スコア / 100点満点</span>
              </div>
              <div class="ranking-table-body">
                ${restRowsHtml}
              </div>
            </div>
          </div>
        `;

        if (typeof lucide !== 'undefined') lucide.createIcons();
      }

      function toggleRankingRowDetail(gate) {
        const drawer = document.getElementById(`ranking-drawer-${gate}`);
        const wrapper = document.getElementById(`ranking-wrapper-${gate}`);
        const btn = document.getElementById(`ranking-toggle-btn-${gate}`);
        const text = document.getElementById(`ranking-toggle-text-${gate}`);
        const arrow = document.getElementById(`ranking-arrow-${gate}`);
        if (!drawer) return;

        const isCurrentlyOpen = drawer.style.display !== 'none';
        if (isCurrentlyOpen) {
          drawer.style.display = 'none';
          if (wrapper) wrapper.classList.remove('is-open');
          if (btn) btn.classList.remove('active');
          if (text) text.innerText = '詳細';
          if (arrow) {
            arrow.innerText = '▾';
            arrow.classList.remove('rotated');
          }
        } else {
          drawer.style.display = 'block';
          if (wrapper) wrapper.classList.add('is-open');
          if (btn) btn.classList.add('active');
          if (text) text.innerText = '閉じる';
          if (arrow) {
            arrow.innerText = '▴';
            arrow.classList.add('rotated');
          }
        }
      }

      function toggleAllRankingDrawers() {
        const drawers = document.querySelectorAll('.ranking-row-drawer');
        const btnToggleAll = document.getElementById('btn-toggle-all-ranking');
        if (!drawers || drawers.length === 0) return;

        let anyClosed = false;
        drawers.forEach(d => {
          if (d.style.display === 'none') anyClosed = true;
        });

        const targetOpen = anyClosed;
        drawers.forEach(d => {
          d.style.display = targetOpen ? 'block' : 'none';
          const gate = d.id.replace('ranking-drawer-', '');
          const wrapper = document.getElementById(`ranking-wrapper-${gate}`);
          const btn = document.getElementById(`ranking-toggle-btn-${gate}`);
          const text = document.getElementById(`ranking-toggle-text-${gate}`);
          const arrow = document.getElementById(`ranking-arrow-${gate}`);

          if (wrapper) {
            if (targetOpen) wrapper.classList.add('is-open');
            else wrapper.classList.remove('is-open');
          }
          if (btn) {
            if (targetOpen) btn.classList.add('active');
            else btn.classList.remove('active');
          }
          if (text) text.innerText = targetOpen ? '閉じる' : '詳細';
          if (arrow) {
            arrow.innerText = targetOpen ? '▴' : '▾';
            if (targetOpen) arrow.classList.add('rotated');
            else arrow.classList.remove('rotated');
          }
        });

        if (btnToggleAll) {
          btnToggleAll.innerText = targetOpen ? '全て閉じる ▴' : '全て展開 ▾';
        }
      }

      function setRankingSort(sortKey) {
        currentRankingSort = sortKey;
        renderContenderRanking();
      }

      function applyRankingToMarks() {
        const currentPred = (PREDICTION_DATA.races && PREDICTION_DATA.races[currentPredictionRaceId]) 
          ? PREDICTION_DATA.races[currentPredictionRaceId] 
          : PREDICTION_DATA;
        if (!currentPred || !currentPred.contenderRanking) return;

        const list = [...currentPred.contenderRanking].sort((a, b) => b.compositeScore - a.compositeScore);
        const marks = {};
        if (list[0]) marks[list[0].gate] = '◎';
        if (list[1]) marks[list[1].gate] = '○';
        if (list[2]) marks[list[2].gate] = '▲';
        if (list[3]) marks[list[3].gate] = '△';
        if (list[4]) marks[list[4].gate] = '△';
        if (list[5]) marks[list[5].gate] = '☆';

        if (typeof localStorage !== 'undefined') {
          localStorage.setItem('keiba_marks_' + currentPredictionRaceId, JSON.stringify(marks));
        }
        updateMarksUI();
        if (typeof renderPredictionMemo === 'function') renderPredictionMemo();

        alert(`好走ランキング上位6頭を予想印に反映しました！

◎ ${list[0].gate}番 ${list[0].horseName}
○ ${list[1].gate}番 ${list[1].horseName}
▲ ${list[2].gate}番 ${list[2].horseName}
△ ${list[3].gate}番 ${list[3].horseName}
△ ${list[4].gate}番 ${list[4].horseName}
☆ ${list[5].gate}番 ${list[5].horseName}`);
      }

      function setPredictionRace(raceId) {
        if (!PREDICTION_DATA.races || !PREDICTION_DATA.races[raceId]) return;
        currentPredictionRaceId = raceId;
        if (typeof localStorage !== 'undefined') {
          localStorage.setItem('keiba_pred_race_id', raceId);
        }
        
        try { initOddsState(); } catch(e) { console.error('initOddsState error:', e); }
        try { initWeightState(); } catch(e) { console.error('initWeightState error:', e); }
        try { renderPredictionRaceSwitcher(); } catch(e) { console.error('renderPredictionRaceSwitcher error:', e); }
        try { renderPredictionHeader(); } catch(e) { console.error('renderPredictionHeader error:', e); }
        try { renderContenderRanking(); } catch(e) { console.error('renderContenderRanking error:', e); }
        try { renderNetkeibaHorseList(); } catch(e) { console.error('renderNetkeibaHorseList error:', e); }
        try { renderPredictionOccult(); } catch(e) { console.error('renderPredictionOccult error:', e); }
        try { renderPredictionMemo(); } catch(e) { console.error('renderPredictionMemo error:', e); }
        try { updateMarksUI(); } catch(e) { console.error('updateMarksUI error:', e); }
        try { updateOddsControlUI(); } catch(e) { console.error('updateOddsControlUI error:', e); }
        try { updateWeightControlUI(); } catch(e) { console.error('updateWeightControlUI error:', e); }
        try { refreshIcons(); } catch(e) {}

        if (window.history && window.history.replaceState) {
          window.history.replaceState({ view: 'prediction', raceId: currentPredictionRaceId }, '', '#prediction-' + currentPredictionRaceId);
        }
      }

      function renderPredictionView() {
        if (typeof document === 'undefined') return;
        const container = document.getElementById('view-prediction');
        if (!container) return;

        if (!currentPredictionRaceId || !PREDICTION_DATA.races || !PREDICTION_DATA.races[currentPredictionRaceId]) {
          const nextRace = getNextUpcomingRace();
          currentPredictionRaceId = (nextRace && PREDICTION_DATA.races && PREDICTION_DATA.races[nextRace.id]) ? nextRace.id : '19';
        }

        try { initOddsState(); } catch(e) { console.error('initOddsState error:', e); }
        try { initWeightState(); } catch(e) { console.error('initWeightState error:', e); }
        try { renderPredictionRaceSwitcher(); } catch(e) { console.error('renderPredictionRaceSwitcher error:', e); }
        try { renderPredictionHeader(); } catch(e) { console.error('renderPredictionHeader error:', e); }
        try { renderContenderRanking(); } catch(e) { console.error('renderContenderRanking error:', e); }
        try { renderNetkeibaHorseList(); } catch(e) { console.error('renderNetkeibaHorseList error:', e); }
        try { renderPredictionOccult(); } catch(e) { console.error('renderPredictionOccult error:', e); }
        try { renderPredictionMemo(); } catch(e) { console.error('renderPredictionMemo error:', e); }
        try { updateMarksUI(); } catch(e) { console.error('updateMarksUI error:', e); }
        try { updateOddsControlUI(); } catch(e) { console.error('updateOddsControlUI error:', e); }
        try { updateWeightControlUI(); } catch(e) { console.error('updateWeightControlUI error:', e); }
        try { refreshIcons(); } catch(e) {}
      }

      // NetKeiba完全準拠 リストレンダラー
      // ユーザー指定の厳格な順序: [馬番] [印] [馬情報] ➔ [オッズ] ➔ [馬体重] ➔ [詳細▼]
      function renderNetkeibaHorseList() {
        if (typeof document === 'undefined') return;
        const listContainer = document.getElementById('netkeiba-horse-list');
        if (!listContainer) return;

        const currentPred = (PREDICTION_DATA.races && PREDICTION_DATA.races[currentPredictionRaceId])
          ? PREDICTION_DATA.races[currentPredictionRaceId]
          : PREDICTION_DATA;
        const rawStarters = getActivePredictionStarters();

        const raceObj = G1_RACES.find(r => r.id === currentPredictionRaceId);
        const venueText = raceObj ? `${raceObj.location}芝・ダート適性` : 'コース適性';

        let starters = rawStarters.map(s => {
          let winVal = s.odds || '--';
          let placeVal = s.placeOdds || '-';
          let popVal = s.pop || 99;

          if (oddsMode === 'live' && liveOddsData && liveOddsData[s.gate]) {
            winVal = liveOddsData[s.gate].win.toFixed(1);
            placeVal = liveOddsData[s.gate].place;
            popVal = liveOddsData[s.gate].pop;
          }

          let jockeyDisplay = `${s.jockey} / ${venueText}`;
          if (currentPred.jockeysCompatibility) {
            const jc = currentPred.jockeysCompatibility.find(j => j.horse === s.horseName || j.jockey === s.jockey);
            if (jc) {
              jockeyDisplay = `${jc.rating} (${jc.switchType})`;
            }
          }

          let rawComment = (s.trainingComment || s.comment || '').trim();
          let hasRealComment = rawComment && rawComment !== '-' && rawComment !== 'null' && rawComment !== 'undefined';
          let commentDisplay = hasRealComment ? rawComment : '-';

          return {
            ...s,
            winOdds: winVal,
            placeOdds: placeVal,
            pop: popVal,
            comment: commentDisplay,
            jockeyStat: jockeyDisplay
          };
        });

        const stage = getRaceEntryStage(currentPredictionRaceId);
        const isGateConfirmed = (stage === 'gate_confirmed');

        const sortGateBtn = document.getElementById('btn-sort-gate');
        if (sortGateBtn) {
          sortGateBtn.innerText = isGateConfirmed ? '馬番順' : '五十音順';
        }

        const stagePill = document.getElementById('odds-stage-pill');
        if (stagePill) {
          if (stage === 'gate_confirmed') {
            stagePill.className = 'nh-stage-pill stage-gates';
            stagePill.innerHTML = `🎯 枠順確定済 (出走${starters.length}頭)`;
          } else if (stage === 'starters_confirmed') {
            stagePill.className = 'nh-stage-pill stage-confirmed';
            stagePill.innerHTML = `🏇 出走馬確定 (枠順未定・五十音順)`;
          } else {
            stagePill.className = 'nh-stage-pill stage-scheduled';
            stagePill.innerHTML = `📋 出馬予定 (枠順未定・五十音順)`;
          }
        }

        if (predictionSortType === 'pop') {
          starters.sort((a, b) => a.pop - b.pop);
        } else if (isGateConfirmed) {
          starters.sort((a, b) => (a.gate || 99) - (b.gate || 99));
        } else {
          // 枠順確定するまでは五十音順
          starters.sort((a, b) => a.horseName.localeCompare(b.horseName, 'ja'));
        }

        const marks = getUserMarks();
        let html = '';

        starters.forEach(s => {
          const horseKey = (s.gate !== null && s.gate !== undefined) ? String(s.gate) : s.horseName.replace(/\s+/g, '');
          const m = marks[horseKey] || marks[s.gate] || marks[s.horseName] || '';
          const mClass = MARK_CLASSES[m] || '';
          const isTop3Pop = s.pop <= 3;
          const displayOdds = s.winOdds || s.odds || '--';

          let gateCellHtml = '';
          if (isGateConfirmed && s.gate) {
            gateCellHtml = `<div class="nh-gate-cell waku-${s.waku}">${s.gate}</div>`;
          } else {
            gateCellHtml = `<div class="nh-gate-cell unconfirmed" title="枠順未確定">-</div>`;
          }

          let displayWeight = '-';
          let displayWeightSub = `<span class="weight-tag-prev">前走</span>`;

          if (s.confirmedWeight) {
            displayWeight = `${s.confirmedWeight}kg`;
            const diff = s.weightDiff || '0';
            let diffClass = 'diff-zero';
            let diffText = (diff === '0' || diff === '+0' || diff === '-0') ? '±0' : diff;
            if (diff.startsWith('+') && diff !== '+0') diffClass = 'diff-plus';
            else if (diff.startsWith('-') && diff !== '-0') diffClass = 'diff-minus';
            displayWeightSub = `<span class="weight-tag-diff ${diffClass}">${diffText}</span>`;
          } else if (s.trainingWeight) {
            displayWeight = `${s.trainingWeight}kg`;
            let diffStr = '';
            if (s.lastRaceWeight) {
              const diffVal = s.trainingWeight - s.lastRaceWeight;
              diffStr = diffVal > 0 ? `+${diffVal}` : (diffVal === 0 ? '±0' : `${diffVal}`);
            }
            displayWeightSub = `<span class="weight-tag-pre" title="調教後馬体重 (前走比 ${diffStr})">調教後${diffStr ? ' ' + diffStr : ''}</span>`;
          } else if (s.lastRaceWeight || s.prevWeight) {
            const pw = s.lastRaceWeight || s.prevWeight;
            displayWeight = `${pw}kg`;
            displayWeightSub = `<span class="weight-tag-prev">前走</span>`;
          } else {
            displayWeight = '-';
            displayWeightSub = `<span style="font-size:10px;color:var(--text-muted);">-</span>`;
          }

          html += `
            <div class="nh-row-container">
              <div class="nh-main-row" data-gate="${horseKey}">
                <!-- 1. 馬番（26px 枠色セル または 未確定ハイフン） -->
                ${gateCellHtml}

                <!-- 2. 印ボタン (30px) -->
                <div class="nh-mark-cell">
                  <button class="nh-mark-btn ${mClass}" data-gate="${horseKey}" aria-label="印選択">
                    ${m}
                  </button>
                </div>

                <!-- 3. 馬情報（中央・可変幅・重なりなし） -->
                <div class="nh-info-cell" data-action="toggle-drawer" data-gate="${horseKey}">
                  <div class="nh-name-row">
                    <span class="nh-horse-name" onclick="event.stopPropagation(); openHorseDetail('${s.horseName}');" title="クリックして競走馬詳細（血統・戦績・写真）を見る">
                    ${s.horseName}
                    <span class="nh-name-info-icon" style="font-size: 10px; margin-left: 4px; padding: 1px 5px; border-radius: 4px; background: rgba(56, 189, 248, 0.15); color: #38bdf8; border: 1px solid rgba(56, 189, 248, 0.3);">詳細</span>
                  </span>
                  </div>
                  <div class="nh-sub-row">
                    <span>${s.sexAge}</span>
                    <span class="nh-jockey">${s.jockey}</span>
                    <span class="nh-load">${s.load}kg</span>
                  </div>
                </div>

                <!-- 4. オッズ・人気（48px固定・右寄せ） -->
                <div class="nh-odds-cell" data-action="toggle-drawer" data-gate="${horseKey}">
                  <div class="nh-odds-line">
                    ${oddsMode === 'estimated' ? '<span class="nh-odds-badge-yosou">予</span>' : ''}
                    <span class="nh-odds-val ${isTop3Pop ? 'highlight-fav' : ''}">${displayOdds}</span>
                  </div>
                  <div class="nh-pop-badge">${s.pop}人気</div>
                </div>

                <!-- 5. 馬体重（52px固定・右寄せ） -->
                <div class="nh-weight-cell" data-action="toggle-drawer" data-gate="${horseKey}">
                  <div class="nh-weight-val">${displayWeight}</div>
                  <div class="nh-weight-sub">${displayWeightSub}</div>
                </div>

                <!-- 6. 詳細▼ボタン (34px固定) -->
                <div class="nh-detail-toggle-cell" data-action="toggle-drawer" data-gate="${horseKey}">
                  <button class="nh-drawer-toggle-btn" id="nh-toggle-btn-${horseKey}" aria-label="詳細展開">
                    <span class="toggle-text" id="nh-toggle-text-${horseKey}">詳細</span>
                    <span class="toggle-arrow" id="nh-arrow-${horseKey}">▾</span>
                  </button>
                </div>
              </div>

              <!-- タップで展開されるアコーディオン詳細 -->
              <div class="nh-detail-drawer" id="nh-drawer-${horseKey}">
                <div class="nh-drawer-content">
                  <!-- 1. 基本ステータス・調教サマリー -->
                  <div class="nh-drawer-grid">
                    <div class="nh-drawer-item">
                      <span class="nh-drawer-label">🏃 総合調教評価</span>
                      ${(() => {
                        const rawG = (s.trainingGrade || '').trim();
                        if (rawG && rawG !== '-' && rawG !== 'null' && rawG !== 'undefined') {
                          const courseStr = s.trainingCourse ? ` ${s.trainingCourse}` : '';
                          const timeStr = s.trainingTime ? ` (${s.trainingTime})` : '';
                          return `<span class="nh-drawer-val-grade grade-${rawG}">【${rawG}】${courseStr}${timeStr}</span>`;
                        }
                        return `<span class="nh-drawer-val">-</span>`;
                      })()}
                    </div>
                    <div class="nh-drawer-item">
                      <span class="nh-drawer-label">📝 調教短評</span>
                      <span class="nh-drawer-val">${s.comment}</span>
                    </div>
                    <div class="nh-drawer-item">
                      <span class="nh-drawer-label">⚖️ 馬体重推移</span>
                      <span class="nh-drawer-val" style="font-size: 11px;">
                        ${(() => {
                          const prevW = s.lastRaceWeight ? `${s.lastRaceWeight}kg` : '-';
                          let trainW = '-';
                          if (s.trainingWeight) {
                            let diffStr = '';
                            if (s.lastRaceWeight) {
                              const d = s.trainingWeight - s.lastRaceWeight;
                              diffStr = d > 0 ? ` (+${d})` : (d === 0 ? ' (±0)' : ` (${d})`);
                            }
                            trainW = `<strong style="color: #a7f3d0;">${s.trainingWeight}kg${diffStr}</strong>`;
                          }
                          const confW = s.confirmedWeight 
                            ? `<strong style="color: var(--gold);">${s.confirmedWeight}kg (${s.weightDiff || '±0'})</strong>` 
                            : '未発表（当日発表次第自動反映）';
                          return `前走: <strong>${prevW}</strong> | 調教後: ${trainW} | 当日確定: ${confW}`;
                        })()}
                      </span>
                    </div>
                    <div class="nh-drawer-item">
                      <span class="nh-drawer-label">🏇 所属厩舎 / 騎手相性</span>
                      <span class="nh-drawer-val">${s.stable || '栗東'} (${s.jockeyStat})</span>
                    </div>
                  </div>

                  <!-- 2. マルチソース調教評価（YouTube / Xトラックマン / 競馬専門紙） -->
                  ${(() => {
                    const rev = s.trainingReviews;
                    if (!rev || (!rev.youtube && !rev.snsX && !rev.media)) return '';
                    return `
                      <div class="nh-drawer-section">
                        <div class="nh-drawer-section-title">
                          <span>📡 マルチソース調教総評 (YouTube / X速報 / 専門紙)</span>
                        </div>
                        <div class="nh-review-grid">
                          ${rev.youtube ? `
                            <div class="nh-review-card yt">
                              <span class="review-source-tag yt">🎥 YouTube解説</span>
                              <span class="review-comment">${rev.youtube}</span>
                            </div>
                          ` : ''}
                          ${rev.snsX ? `
                            <div class="nh-review-card x">
                              <span class="review-source-tag x">📱 X/トラックマン</span>
                              <span class="review-comment">${rev.snsX}</span>
                            </div>
                          ` : ''}
                          ${rev.media ? `
                            <div class="nh-review-card media">
                              <span class="review-source-tag media">📰 専門紙総評</span>
                              <span class="review-comment">${rev.media}</span>
                            </div>
                          ` : ''}
                        </div>
                      </div>
                    `;
                  })()}

                  <!-- 3. 血統 ＆ 距離・馬場適性分析 -->
                  ${(() => {
                    const ped = s.pedigree;
                    const apt = s.aptitude;
                    if (!ped && !apt) return '';
                    return `
                      <div class="nh-drawer-section">
                        <div class="nh-drawer-section-title">
                          <span>🧬 血統背景 ＆ 距離・馬場適性分析</span>
                        </div>
                        ${ped ? `
                          <div class="nh-pedigree-box">
                            <div>父: <strong style="color:#fff;">${ped.sire || '-'}</strong> <span style="font-size:10.5px;color:var(--text-muted);">(${ped.lineage || '-'})</span></div>
                            <div>母: <strong style="color:#fff;">${ped.dam || '-'}</strong> <span style="font-size:10.5px;color:var(--text-muted);">(母父: ${ped.broodmareSire || '-'})</span></div>
                            ${ped.feature ? `<div style="grid-column: 1 / -1; color: var(--text-muted); font-size: 11px;">💡 特徴: ${ped.feature}</div>` : ''}
                          </div>
                        ` : ''}
                        ${apt ? `
                          <div class="nh-aptitude-tags">
                            ${apt.distance ? `<span class="aptitude-pill dist">🏃 距離: ${apt.distance}</span>` : ''}
                            ${apt.trackCondition ? `<span class="aptitude-pill going">🌱 馬場: ${apt.trackCondition}</span>` : ''}
                            ${apt.runningStyle ? `<span class="aptitude-pill style">⚡ 脚質: ${apt.runningStyle}</span>` : ''}
                            ${apt.courseFitness ? `<span class="aptitude-pill">🏟️ コース: ${apt.courseFitness}</span>` : ''}
                          </div>
                        ` : ''}
                      </div>
                    `;
                  })()}

                  <!-- 4. 前走リザルト ＆ 勝因・敗因分析 -->
                  ${(() => {
                    const prev = s.prevRace;
                    if (!prev) return '';
                    let rankClass = 'prev-rank-other';
                    if (prev.finish && prev.finish.startsWith('1着')) rankClass = 'prev-rank-1';
                    else if (prev.finish && prev.finish.startsWith('2着')) rankClass = 'prev-rank-2';
                    else if (prev.finish && prev.finish.startsWith('3着')) rankClass = 'prev-rank-3';

                    return `
                      <div class="nh-drawer-section">
                        <div class="nh-drawer-section-title">
                          <span>📊 前走リザルト ＆ 勝ち負けの要因 (勝因・敗因分析)</span>
                        </div>
                        <div class="nh-prev-race-row">
                          <span class="prev-race-badge">${prev.raceName || '前走'}</span>
                          <span class="prev-rank-badge ${rankClass}">${prev.finish || '-'}</span>
                          <span>${prev.date || ''} (${prev.venue || ''})</span>
                          <span>人気: <strong>${prev.pop || '-'}</strong></span>
                          <span>騎手: <strong>${prev.jockey || '-'}</strong></span>
                          <span>上がり3F: <strong style="color:var(--gold);">${prev.agari || '-'}</strong></span>
                          <span>着差: <strong>${prev.margin || '-'}</strong></span>
                          ${prev.weight ? `<span>馬体重: <strong>${prev.weight}kg</strong></span>` : ''}
                        </div>
                        ${prev.factor ? `
                          <div class="factor-analysis-box">
                            <span class="factor-label">🎯 勝因・敗因分析（前走の教訓と今回の狙い）</span>
                            <div class="factor-text">${prev.factor}</div>
                          </div>
                        ` : ''}
                      </div>
                    `;
                  })()}
                </div>
              </div>
            </div>
          `;
        });

        listContainer.innerHTML = html;
        bindHorseListEvents();
      }

      function bindHorseListEvents() {
        document.querySelectorAll('.nh-mark-btn').forEach(btn => {
          btn.addEventListener('click', (e) => {
            e.stopPropagation();
            const gate = btn.getAttribute('data-gate');
            openMarkSheet(gate);
          });
        });

        document.querySelectorAll('[data-action="toggle-drawer"]').forEach(el => {
          el.addEventListener('click', () => {
            const gate = el.getAttribute('data-gate');
            toggleHorseDrawer(gate);
          });
        });
      }

      function toggleHorseDrawer(gate) {
        const drawer = document.getElementById(`nh-drawer-${gate}`);
        const btn = document.getElementById(`nh-toggle-btn-${gate}`);
        const text = document.getElementById(`nh-toggle-text-${gate}`);
        const arrow = document.getElementById(`nh-arrow-${gate}`);

        if (!drawer) return;

        const isOpen = drawer.classList.contains('open');
        if (isOpen) {
          drawer.classList.remove('open');
          if (btn) btn.classList.remove('active');
          if (text) text.innerText = '詳細';
          if (arrow) arrow.innerText = '▾';
        } else {
          drawer.classList.add('open');
          if (btn) btn.classList.add('active');
          if (text) text.innerText = '閉じる';
          if (arrow) arrow.innerText = '▴';
        }
      }

      function renderPredictionOccult() {
        if (typeof document === 'undefined') return;
        const list = document.getElementById('occult-cards-list');
        if (!list) return;

        const currentPred = (PREDICTION_DATA.races && PREDICTION_DATA.races[currentPredictionRaceId])
          ? PREDICTION_DATA.races[currentPredictionRaceId]
          : PREDICTION_DATA;

        const occultSigns = currentPred.occultSigns || [];
        if (occultSigns.length === 0) {
          list.innerHTML = '<div style="padding:16px;text-align:center;color:var(--text-muted);">オカルトサイン考察は順次公開されます</div>';
          return;
        }

        list.innerHTML = occultSigns.map(s => {
          const targetsHtml = (s.targets || []).map(t => {
            const hasGate = (t.gate != null);
            return `
              <span class="occult-target-pill">
                ${hasGate ? `<span class="nh-gate-cell waku-${t.waku || 1}" style="width:18px;height:18px;font-size:10px;border-radius:3px;">${t.gate}</span>` : `<span style="font-size:11px;opacity:0.8;">🐴</span>`}
                <span>${t.name}</span>
              </span>
            `;
          }).join('');

          return `
            <div class="occult-card">
              <div class="occult-card-header">
                <span class="occult-badge">${s.badge || '🔮 サイン'}</span>
                <span class="occult-source">${s.source || 'X・SNS話題'}</span>
              </div>
              <h4 class="occult-card-title">${s.title}</h4>
              <p class="occult-card-content">${s.content}</p>
              ${targetsHtml ? `
                <div class="occult-card-targets">
                  <span style="font-size:11px;color:var(--gold);font-weight:700;">🎯 該当推奨馬:</span>
                  ${targetsHtml}
                </div>
              ` : ''}
            </div>
          `;
        }).join('');
      }

      function renderPredictionMemo() {
        if (typeof document === 'undefined') return;
        const memoInput = document.getElementById('prediction-user-memo');
        if (memoInput && typeof localStorage !== 'undefined') {
          const saved = localStorage.getItem('keiba_memo_' + currentPredictionRaceId);
          memoInput.value = saved || '';
        }
      }

      function initPredictionEventListeners() {
        if (typeof document === 'undefined') return;

        const btnBack = document.getElementById('btn-back-to-calendar');
        if (btnBack) {
          btnBack.addEventListener('click', () => {
            switchAppView('calendar', true);
          });
        }

        const btnManualSync = document.getElementById('btn-manual-sync');
        if (btnManualSync) {
          btnManualSync.addEventListener('click', () => {
            btnManualSync.classList.add('rotating');
            btnManualSync.innerHTML = '🔄 同期中...';
            setTimeout(() => {
              btnManualSync.classList.remove('rotating');
              btnManualSync.innerHTML = '✓ 最新データ反映済';
              if (typeof renderPredictionView === 'function') renderPredictionView();
              setTimeout(() => {
                btnManualSync.innerHTML = '<i data-lucide="refresh-cw" style="width: 11px; height: 11px;"></i> 最新データ同期';
                if (typeof lucide !== 'undefined') lucide.createIcons();
              }, 2000);
            }, 600);
          });
        }

        const btnEst = document.getElementById('btn-odds-estimated');
        const btnLive = document.getElementById('btn-odds-live');
        if (btnEst) {
          btnEst.addEventListener('click', () => setOddsMode('estimated'));
        }
        if (btnLive) {
          btnLive.addEventListener('click', () => setOddsMode('live'));
        }

        const btnRefresh = document.getElementById('btn-refresh-odds');
        if (btnRefresh) {
          btnRefresh.addEventListener('click', () => {
            btnRefresh.classList.add('rotating');
            setTimeout(() => btnRefresh.classList.remove('rotating'), 600);
            refreshLiveOdds(true);
          });
        }

        const sortGateBtn = document.getElementById('btn-sort-gate');
        const sortPopBtn = document.getElementById('btn-sort-pop');

        if (sortGateBtn) {
          sortGateBtn.addEventListener('click', () => {
            predictionSortType = 'gate';
            sortGateBtn.classList.add('active');
            if (sortPopBtn) sortPopBtn.classList.remove('active');
            renderNetkeibaHorseList();
          });
        }
        if (sortPopBtn) {
          sortPopBtn.addEventListener('click', () => {
            predictionSortType = 'pop';
            sortPopBtn.classList.add('active');
            if (sortGateBtn) sortGateBtn.classList.remove('active');
            renderNetkeibaHorseList();
          });
        }

        const btnCloseSheet = document.getElementById('btn-close-sheet');
        const sheetBackdrop = document.getElementById('mark-sheet-backdrop');
        if (btnCloseSheet) btnCloseSheet.addEventListener('click', closeMarkSheet);
        if (sheetBackdrop) sheetBackdrop.addEventListener('click', closeMarkSheet);

        document.querySelectorAll('.btn-sheet-mark').forEach(btn => {
          btn.addEventListener('click', () => {
            const mark = btn.getAttribute('data-mark');
            if (activeSheetGate) {
              setUserMark(activeSheetGate, mark);
            }
            closeMarkSheet();
          });
        });

        const memoInput = document.getElementById('prediction-user-memo');
        const saveStatus = document.getElementById('memo-save-status');
        const btnClearMemo = document.getElementById('btn-clear-memo');

        if (memoInput) {
          let memoTimer = null;
          memoInput.addEventListener('input', () => {
            if (saveStatus) saveStatus.innerText = '編集中...';
            if (memoTimer) clearTimeout(memoTimer);
            memoTimer = setTimeout(() => {
              if (typeof localStorage !== 'undefined') {
                localStorage.setItem('keiba_memo_' + currentPredictionRaceId, memoInput.value);
              }
              if (saveStatus) {
                saveStatus.innerText = '💾 自動保存完了';
                setTimeout(() => { saveStatus.innerText = ''; }, 2000);
              }
            }, 600);
          });
        }

        if (btnClearMemo && memoInput) {
          btnClearMemo.addEventListener('click', () => {
            memoInput.value = '';
            if (typeof localStorage !== 'undefined') {
              localStorage.removeItem('keiba_memo_' + currentPredictionRaceId);
            }
            if (saveStatus) saveStatus.innerText = '🗑️ 消去完了';
          });
        }
      }

      function switchAppView(viewName, pushState = true) {
        switchView(viewName, true, false);
        if (pushState && window.history) {
          const targetHash = (viewName === 'prediction') ? ('#prediction-' + currentPredictionRaceId) : '#calendar';
          window.history.pushState({ view: viewName, raceId: currentPredictionRaceId }, '', targetHash);
        }
      }



      // ========================================================
      // レース回顧＆次回への参考データ ロジック
      // ========================================================
      let currentReviewRaceId = '18';
      let currentReviewFilter = 'all';

      function renderReviewPills() {
        const autumnContainer = document.getElementById('review-pills-autumn');
        const springContainer = document.getElementById('review-pills-spring');
        if (!autumnContainer || !springContainer) return;

        const autumnRaces = [
          { id: '18', name: 'マイルCS', num: '第43回' },
          { id: '17', name: 'エリザベス女王杯', num: '第51回' },
          { id: '16', name: '天皇賞（秋）', num: '第172回' },
          { id: '15', name: '菊花賞', num: '第87回' },
          { id: '14', name: '秋華賞', num: '第31回' },
          { id: '13', name: 'スプリンターズS', num: '第60回' }
        ];

        const springRaces = [
          { id: '12', name: '宝塚記念', num: '第67回' },
          { id: '11', name: '安田記念', num: '第76回' },
          { id: '10', name: '日本ダービー', num: '第93回' },
          { id: '9', name: 'オークス', num: '第87回' },
          { id: '8', name: 'ヴィクトリアM', num: '第21回' },
          { id: '7', name: 'NHKマイルC', num: '第31回' },
          { id: '6', name: '天皇賞（春）', num: '第173回' },
          { id: '5', name: '皐月賞', num: '第86回' },
          { id: '4', name: '桜花賞', num: '第86回' },
          { id: '3', name: '大阪杯', num: '第70回' },
          { id: '2', name: '高松宮記念', num: '第56回' },
          { id: '1', name: 'フェブラリーS', num: '第43回' }
        ];

        autumnContainer.innerHTML = autumnRaces.map(r => `
          <button class="review-pill ${r.id === currentReviewRaceId ? 'active' : ''}" onclick="selectReviewRace('${r.id}')">
            <span class="review-pill-num">${r.num}</span>
            <span>${r.name}</span>
          </button>
        `).join('');

        springContainer.innerHTML = springRaces.map(r => `
          <button class="review-pill ${r.id === currentReviewRaceId ? 'active' : ''}" onclick="selectReviewRace('${r.id}')">
            <span class="review-pill-num">${r.num}</span>
            <span>${r.name}</span>
          </button>
        `).join('');
      }

      function selectReviewRace(raceId, shouldScroll = false) {
        currentReviewRaceId = String(raceId);
        currentReviewFilter = 'all';
        renderReviewPills();
        renderReviewContent(currentReviewRaceId);

        if (typeof window !== 'undefined' && window.location) {
          const targetHash = '#review-' + raceId;
          if (window.location.hash !== targetHash) {
            if (window.history && window.history.replaceState) {
              window.history.replaceState(null, '', targetHash);
            } else {
              window.location.hash = targetHash;
            }
          }
          if (typeof localStorage !== 'undefined') {
            localStorage.setItem('keiba_active_route', targetHash);
            localStorage.setItem('keiba_last_main_view', 'review');
          }
        }

        if (shouldScroll && typeof window !== 'undefined' && window.scrollTo) {
          const container = document.getElementById('review-main-container');
          if (container) {
            container.scrollIntoView({ behavior: 'smooth', block: 'start' });
          }
        }
      }

      let currentDeviationSort = 'rank'; // 'rank' | 'finish' | 'surge' | 'drop'

      function setReviewFilter(filterType) {
        currentReviewFilter = filterType;
        const filterBtns = document.querySelectorAll('.btn-review-filter');
        filterBtns.forEach(btn => {
          if (btn.getAttribute('data-filter') === filterType) btn.classList.add('active');
          else btn.classList.remove('active');
        });
        renderFilteredHorsesList();
      }

      // ========================================================
      // 好走ランク vs 確定着順 乖離分析ヘルパー
      // ========================================================
      function getDeviationBadge(diff) {
        if (diff >= 5) {
          return `<span class="dev-badge super-surge">⚡ 超激走 (+${diff})</span>`;
        } else if (diff >= 1) {
          return `<span class="dev-badge surge">▲ 好走 (+${diff})</span>`;
        } else if (diff === 0) {
          return `<span class="dev-badge match">🎯 一致 (±0)</span>`;
        } else if (diff === -1) {
          return `<span class="dev-badge match">🎯 ほぼ的中 (-1)</span>`;
        } else if (diff >= -4) {
          return `<span class="dev-badge slight-drop">▼ 惜敗 (${diff})</span>`;
        } else {
          return `<span class="dev-badge drop">✕ 凡走 (${diff})</span>`;
        }
      }

      function getContenderDeviationList(raceId) {
        let resultsList = [];
        if (typeof RESULTS_DATA !== 'undefined' && RESULTS_DATA[raceId]) {
          const raw = RESULTS_DATA[raceId].horses || RESULTS_DATA[raceId];
          if (Array.isArray(raw)) {
            resultsList = raw.map(r => {
              if (Array.isArray(r)) {
                return {
                  rank: r[0],
                  gate: r[1],
                  name: r[2],
                  sexAge: r[3],
                  load: r[4],
                  jockey: r[5],
                  time: r[6],
                  margin: r[7],
                  passing: r[8],
                  agari: r[9],
                  odds: r[10],
                  pop: r[11],
                  stable: r[14]
                };
              } else {
                return {
                  rank: r.rank,
                  gate: r.gate,
                  name: r.name || r.horseName,
                  sexAge: r.sexAge,
                  load: r.load,
                  jockey: r.jockey,
                  time: r.time,
                  margin: r.margin,
                  passing: r.passing,
                  agari: r.agari,
                  odds: r.odds,
                  pop: r.pop,
                  stable: r.stable
                };
              }
            });
          }
        }

        const resMap = {};
        resultsList.forEach(r => {
          resMap[r.name] = r;
        });

        const revMap = {};
        if (typeof RACE_REVIEWS_DATA !== 'undefined' && RACE_REVIEWS_DATA[raceId] && RACE_REVIEWS_DATA[raceId].horseReviews) {
          RACE_REVIEWS_DATA[raceId].horseReviews.forEach(hr => {
            revMap[hr.name] = hr;
          });
        }

        let contenders = [];
        if (typeof PREDICTION_DATA !== 'undefined') {
          if (PREDICTION_DATA.races && PREDICTION_DATA.races[raceId] && PREDICTION_DATA.races[raceId].contenderRanking) {
            contenders = PREDICTION_DATA.races[raceId].contenderRanking;
          } else if (raceId === PREDICTION_DATA.activeRaceId && PREDICTION_DATA.contenderRanking) {
            contenders = PREDICTION_DATA.contenderRanking;
          }
        }

        if (contenders.length === 0 && resultsList.length > 0) {
          contenders = resultsList.map((r, idx) => {
            return {
              rank: idx + 1,
              horseName: r.name,
              gate: r.gate,
              jockey: r.jockey,
              load: r.load,
              odds: r.odds,
              pop: r.pop,
              recommendedMark: idx === 0 ? '◎' : (idx === 1 ? '○' : (idx === 2 ? '▲' : (idx <= 4 ? '△' : '-'))),
              compositeScore: (95 - idx * 1.2).toFixed(1)
            };
          });
        }

        return contenders.map(c => {
          const r = resMap[c.horseName] || {};
          const hr = revMap[c.horseName] || {};
          const finishRank = (r.rank !== undefined && r.rank !== null && !isNaN(Number(r.rank))) 
            ? Number(r.rank) 
            : (hr.rank && !isNaN(Number(hr.rank)) ? Number(hr.rank) : 99);
          
          const diff = (finishRank !== 99 && c.rank) ? (c.rank - finishRank) : 0;
          
          let factorText = hr.factor || hr.review || '-';
          if (factorText.length > 90) factorText = factorText.slice(0, 87) + '...';

          return {
            rank: c.rank,
            mark: c.recommendedMark || '-',
            score: c.compositeScore,
            grade: c.grade || '-',
            gate: c.gate || r.gate || hr.gate || '-',
            horseName: c.horseName,
            jockey: c.jockey || r.jockey || hr.jockey || '-',
            load: c.load || r.load || hr.load || '-',
            finishRank: finishRank,
            pop: r.pop || hr.pop || c.pop,
            odds: r.odds || hr.odds || c.odds,
            diff: diff,
            factor: factorText
          };
        });
      }

      function getHorseDeviationInfo(raceId, horseName) {
        const list = getContenderDeviationList(raceId);
        return list.find(x => x.horseName === horseName) || null;
      }

      function renderDeviationTable(raceId) {
        const tbody = document.getElementById('deviation-table-body');
        if (!tbody) return;

        const list = getContenderDeviationList(raceId);
        if (!list || list.length === 0) {
          tbody.innerHTML = '<tr><td colspan="6" style="text-align:center;padding:24px;color:#94a3b8;">好走ランクデータが集計中です。</td></tr>';
          return;
        }

        let sorted = [...list];
        if (currentDeviationSort === 'finish') {
          sorted.sort((a, b) => a.finishRank - b.finishRank);
        } else if (currentDeviationSort === 'surge') {
          sorted.sort((a, b) => b.diff - a.diff);
        } else if (currentDeviationSort === 'drop') {
          sorted.sort((a, b) => a.diff - b.diff);
        } else {
          sorted.sort((a, b) => a.rank - b.rank);
        }

        tbody.innerHTML = sorted.map(item => {
          let finishRankClass = 'review-rank-other';
          if (item.finishRank === 1) finishRankClass = 'review-rank-1';
          else if (item.finishRank === 2) finishRankClass = 'review-rank-2';
          else if (item.finishRank === 3) finishRankClass = 'review-rank-3';

          const finishRankText = item.finishRank === 99 ? '取消/除外' : `${item.finishRank}着`;
          const devBadge = getDeviationBadge(item.diff);

          return `
            <tr class="dev-row">
              <td>
                <div class="dev-rank-cell">
                  <span class="dev-rank-num dev-num-${item.rank}">${item.rank}位</span>
                  <span class="dev-mark-pill">${item.mark || '-'}</span>
                  <span class="dev-score-pill">${item.score}点</span>
                </div>
              </td>
              <td>
                <div class="dev-horse-cell">
                  <span class="target-gate-circle" style="background:#334155; flex-shrink: 0;">${item.gate}</span>
                  <div>
                    <span class="dev-horse-name" onclick="openHorseDetail('${item.horseName}')" style="cursor: pointer; text-decoration: underline;" title="競走馬詳細を見る">${item.horseName}</span>
                    <span class="dev-jockey-text">${item.jockey} (${item.load}kg)</span>
                  </div>
                </div>
              </td>
              <td style="text-align: center;">
                <span class="review-rank-badge ${finishRankClass}">${finishRankText}</span>
              </td>
              <td style="text-align: center;">
                <span class="dev-pop-text">${item.pop ? item.pop + '人気' : '-'}</span>
                <span class="dev-odds-text">${item.odds ? item.odds + '倍' : ''}</span>
              </td>
              <td style="text-align: center;">
                ${devBadge}
              </td>
              <td>
                <div class="dev-factor-text">
                  ${item.factor}
                </div>
              </td>
            </tr>
          `;
        }).join('');
      }

      function setDeviationSort(sortType) {
        currentDeviationSort = sortType;
        const btns = document.querySelectorAll('.btn-dev-sort');
        btns.forEach(btn => {
          if (btn.getAttribute('data-sort') === sortType) btn.classList.add('active');
          else btn.classList.remove('active');
        });
        renderDeviationTable(currentReviewRaceId);
      }

      function renderFilteredHorsesList() {
        const listContainer = document.getElementById('horse-reviews-list-container');
        if (!listContainer) return;

        const data = (typeof RACE_REVIEWS_DATA !== 'undefined' && RACE_REVIEWS_DATA[currentReviewRaceId]) 
          ? RACE_REVIEWS_DATA[currentReviewRaceId] 
          : null;
        if (!data) {
          listContainer.innerHTML = '<div style="padding: 16px; color: #94a3b8; font-size: 13px;">個別回顧データは集計中です。</div>';
          return;
        }

        // Full field guarantee: combine reviews data with RESULTS_DATA if any missing
        let allReviews = [...(data.horseReviews || [])];
        if (typeof RESULTS_DATA !== 'undefined' && RESULTS_DATA[currentReviewRaceId]) {
          const resList = RESULTS_DATA[currentReviewRaceId].horses || RESULTS_DATA[currentReviewRaceId];
          if (Array.isArray(resList)) {
            const existingGates = new Set(allReviews.map(h => Number(h.gate)));
            resList.forEach(rh => {
              const rGate = Array.isArray(rh) ? rh[1] : rh.gate;
              if (!existingGates.has(Number(rGate))) {
                const rRank = Array.isArray(rh) ? rh[0] : rh.rank;
                const rName = Array.isArray(rh) ? rh[2] : (rh.horseName || rh.name);
                const rJockey = Array.isArray(rh) ? rh[5] : rh.jockey;
                const rLoad = Array.isArray(rh) ? rh[4] : rh.load;
                const rTime = Array.isArray(rh) ? rh[6] : rh.time;
                const rMargin = Array.isArray(rh) ? rh[7] : rh.margin;
                const rPassing = Array.isArray(rh) ? rh[8] : rh.passing;
                const rAgari = Array.isArray(rh) ? rh[9] : rh.agari;
                allReviews.push({
                  rank: rRank, gate: rGate, name: rName, jockey: rJockey, load: rLoad,
                  time: rTime, margin: rMargin, passing: rPassing, agari: rAgari, agariRank: 5,
                  review: `道中は後方追走から直線も脚を伸ばしたが${rRank}着まで。本領発揮とはいかなかった。`,
                  factor: '【敗因】ペース適性のズレまたは直線での進路・距離の壁。',
                  nextCondition: '次走得意なコース・条件への変更で巻き返し狙い。',
                  jockeyComment: null
                });
              }
            });
          }
        }
        allReviews.sort((a, b) => (parseInt(a.sortRank || a.rank) || 99) - (parseInt(b.sortRank || b.rank) || 99));

        // Update count badges on filter buttons
        const pickupNames = (data.nextRaceInsights && data.nextRaceInsights.targetHorses) 
          ? data.nextRaceInsights.targetHorses.map(t => t.name) 
          : [];
        const btnAll = document.querySelector('.btn-review-filter[data-filter="all"]');
        const btnPickup = document.querySelector('.btn-review-filter[data-filter="pickup"]');
        const btnPodium = document.querySelector('.btn-review-filter[data-filter="podium"]');
        const btnDis = document.querySelector('.btn-review-filter[data-filter="disadvantage"]');

        if (btnAll) btnAll.innerText = `全頭表示 (${allReviews.length}頭)`;
        if (btnPickup) btnPickup.innerText = `🎯 次走注目・危険馬 (${allReviews.filter(h => pickupNames.includes(h.name)).length})`;
        if (btnPodium) btnPodium.innerText = `🏆 上位入線 (3)`;
        if (btnDis) btnDis.innerText = `⚠️ 不利・敗因あり (${allReviews.filter(h => h.factor && (h.factor.includes('不利') || h.factor.includes('壁') || h.factor.includes('詰まり') || h.factor.includes('ロス') || h.factor.includes('反動') || h.factor.includes('外々'))).length})`;

        let filtered = allReviews;
        if (currentReviewFilter === 'pickup') {
          filtered = allReviews.filter(h => pickupNames.includes(h.name));
        } else if (currentReviewFilter === 'podium') {
          filtered = allReviews.filter(h => parseInt(h.sortRank || h.rank) <= 3);
        } else if (currentReviewFilter === 'disadvantage') {
          filtered = allReviews.filter(h => h.factor && (h.factor.includes('不利') || h.factor.includes('壁') || h.factor.includes('詰まり') || h.factor.includes('ロス') || h.factor.includes('反動') || h.factor.includes('外々')));
        }

        if (filtered.length === 0) {
          listContainer.innerHTML = '<div style="padding: 16px; color: #94a3b8; font-size: 13px;">該当する馬はいません。</div>';
          return;
        }

        listContainer.innerHTML = filtered.map(h => {
          let rankClass = 'review-rank-other';
          if (h.rank === 1 || h.rank === '1') rankClass = 'review-rank-1';
          else if (h.rank === 2 || h.rank === '2') rankClass = 'review-rank-2';
          else if (h.rank === 3 || h.rank === '3') rankClass = 'review-rank-3';
          else if (typeof h.rank === 'string' && isNaN(Number(h.rank))) rankClass = 'review-rank-cancel';

          const rankText = (typeof h.rank === 'number' || !isNaN(Number(h.rank))) ? `${h.rank}着` : h.rank;
          const timeText = (h.time && h.time !== '-') ? `<b>${h.time}</b> ${h.margin && h.margin !== '-' ? `(${h.margin})` : ''}` : '-';
          const agariText = (h.agari && h.agari !== '-') ? `<b>${h.agari}</b> ${h.agariRank && h.agariRank !== '-' ? `(${h.agariRank}位)` : ''}` : '-';

          const devInfo = getHorseDeviationInfo(currentReviewRaceId, h.name);

          return `
            <div class="horse-review-row">
              <div class="horse-review-row-header">
                <div class="horse-review-basic-info">
                  <span class="review-rank-badge ${rankClass}">${rankText}</span>
                  <div class="target-gate-circle" style="background:#334155;">${h.gate}</div>
                  <span class="horse-review-name" onclick="openHorseDetail('${h.name}')" style="cursor: pointer; text-decoration: underline;" title="クリックして競走馬詳細を見る">${h.name}</span>
                  <span class="horse-review-meta">${h.jockey} (${h.load}kg)</span>
                </div>

                ${devInfo ? `
                  <div class="horse-review-contender-tag">
                    <span class="dev-inline-label">好走ランク:</span>
                    <span class="dev-inline-rank">${devInfo.rank}位 (${devInfo.mark} ${devInfo.score}点)</span>
                    <span class="dev-inline-arrow">➔</span>
                    ${getDeviationBadge(devInfo.diff)}
                  </div>
                ` : ''}

                <div class="horse-review-time-info">
                  <span>${timeText}</span>
                  <span>通過: ${h.passing || '-'}</span>
                  <span>上がり: ${agariText}</span>
                </div>
              </div>

              <div class="horse-review-detail-grid">
                <div class="review-detail-col">
                  <span class="review-detail-label">📋 レース内容・走行評価</span>
                  <p class="review-detail-text">${h.review}</p>
                </div>
                <div class="review-detail-col">
                  <span class="review-detail-label">🔍 勝因 / 敗因の核心</span>
                  <p class="review-detail-text" style="color: #cbd5e1;">${h.factor}</p>
                </div>
              </div>

              <div style="background: rgba(16, 185, 129, 0.08); border: 1px solid rgba(16, 185, 129, 0.25); border-radius: 6px; padding: 10px 12px;">
                <div style="font-size: 11px; font-weight: 800; color: #34d399; margin-bottom: 2px;">🎯 次走狙い目条件＆推奨レース</div>
                <div style="font-size: 12.5px; color: #f1f5f9; line-height: 1.45;">${h.nextCondition}</div>
              </div>

              ${h.jockeyComment ? `
                <div class="review-jockey-quote">${h.jockeyComment}</div>
              ` : ''}
            </div>
          `;
        }).join('');
      }

      function renderReviewContent(raceId) {
        const container = document.getElementById('review-main-container');
        if (!container) return;

        const data = (typeof RACE_REVIEWS_DATA !== 'undefined' && RACE_REVIEWS_DATA[raceId]) 
          ? RACE_REVIEWS_DATA[raceId] 
          : null;

        if (!data) {
          container.innerHTML = `
            <div class="review-card" style="text-align: center; padding: 40px 20px;">
              <i data-lucide="info" style="width: 36px; height: 36px; color: #94a3b8; margin-bottom: 12px;"></i>
              <h3 style="font-size: 16px; color: #f1f5f9; margin-bottom: 6px;">レース回顧・次走分析データを集計中</h3>
              <p style="font-size: 13px; color: #94a3b8; margin: 0;">レース終了および公式ラップ・関係者コメント確定後に順次公開されます。</p>
            </div>
          `;
          if (typeof lucide !== 'undefined') lucide.createIcons();
          return;
        }

        // Lap Times Bar Chart
        let lapBarsHtml = '';
        if (data.pace && data.pace.lapTimes && data.pace.lapTimes.length > 0) {
          const lTimes = data.pace.lapTimes.map(t => parseFloat(t));
          const minL = Math.min(...lTimes);
          const maxL = Math.max(...lTimes);
          const range = (maxL - minL) || 1;

          lapBarsHtml = `
            <div class="lap-graph-wrapper">
              <div class="lap-graph-title">📊 1ハロン毎のラップタイム推移 (200m毎)</div>
              <div class="lap-bars-container">
                ${data.pace.lapTimes.map((t, idx) => {
                  const val = parseFloat(t);
                  const pct = Math.max(20, Math.min(100, 100 - ((val - minL) / range) * 70));
                  return `
                    <div class="lap-bar-col">
                      <span class="lap-bar-val">${t}</span>
                      <div class="lap-bar-fill" style="height: ${pct}%;"></div>
                      <span class="lap-bar-idx">${idx + 1}F</span>
                    </div>
                  `;
                }).join('')}
              </div>
            </div>
          `;
        }

        // Contender Deviation KPI calculation
        const devList = getContenderDeviationList(raceId);
        const surgeHorses = [...devList].sort((a, b) => b.diff - a.diff).filter(x => x.diff >= 4);
        const dropHorses = [...devList].sort((a, b) => a.diff - b.diff).filter(x => x.diff <= -4);
        const top5Contenders = devList.filter(x => x.rank <= 5);
        const podiumHorsesInTop5 = top5Contenders.filter(x => x.finishRank <= 3);

        let matchTitle = '指数通り順当決着';
        let matchSub = '好走上位馬が実力を発揮したレース展開。';
        if (podiumHorsesInTop5.length >= 3) {
          matchTitle = '好走TOP5が1〜3着を完全独占！';
          matchSub = `事前評価TOP5の3頭（${podiumHorsesInTop5.map(x=>x.horseName).join('・')}）が上位を独占。3連単・3連複的中圏内。`;
        } else if (podiumHorsesInTop5.length === 2) {
          matchTitle = '好走TOP5から2頭が連対・好走！';
          matchSub = `事前評価上位の${podiumHorsesInTop5.map(x=>x.horseName).join('・')}が馬券圏内に好走。`;
        } else if (podiumHorsesInTop5.length === 1) {
          matchTitle = '上位評価馬から1頭が入線';
          matchSub = `波乱の展開となり、伏兵の台頭が見られました。`;
        } else {
          matchTitle = '波乱の指数乖離決着';
          matchSub = '好走上位馬が苦戦し、穴馬の激走が相次ぐ大波乱の決着となりました。';
        }

        let surgeTitle = '該当なし';
        let surgeSub = '事前ランクを大きく上回る激走馬はいませんでした。';
        if (surgeHorses.length > 0) {
          const best = surgeHorses[0];
          surgeTitle = `${best.horseName} (好走${best.rank}位 ➔ 確定${best.finishRank}着 / +${best.diff}ランク)`;
          surgeSub = best.factor || '事前の好走評価を大幅に覆す圧巻の激走を披露しました。';
        }

        let dropTitle = '該当なし';
        let dropSub = '事前ランクから大きく下振れた馬はいませんでした。';
        if (dropHorses.length > 0) {
          const worst = dropHorses[0];
          dropTitle = `${worst.horseName} (好走${worst.rank}位 ➔ 確定${worst.finishRank}着 / ${worst.diff}ランク)`;
          dropSub = worst.factor || '前評判や好走指数通りの走りができず、大敗を喫しました。';
        }

        // Target Horses Cards (Pickup & Danger)
        let targetHorsesHtml = '';
        if (data.nextRaceInsights && data.nextRaceInsights.targetHorses) {
          targetHorsesHtml = data.nextRaceInsights.targetHorses.map(t => {
            const bType = t.badgeType || 'pickup';
            return `
              <div class="target-horse-card ${bType}">
                <div class="target-card-header">
                  <div class="target-horse-name-row">
                    <div class="target-gate-circle">${t.gate}</div>
                    <div>
                      <span class="target-horse-name" onclick="openHorseDetail('${t.name}')" style="cursor: pointer; text-decoration: underline;" title="クリックして競走馬詳細を見る">${t.name}</span>
                      <span class="target-horse-rank">(${t.finishRank})</span>
                    </div>
                  </div>
                  <span class="target-tag-badge ${bType}">${t.tag}</span>
                </div>

                <div class="target-reason">${t.reason}</div>

                <div class="target-condition-box ${bType}">
                  <div class="target-condition-title">${bType === 'danger' ? '⚠️ 次走危険な条件・パターン' : '🎯 次走狙い目条件'}</div>
                  <div>${t.nextTargetCondition}</div>
                  ${t.recommendedRace ? `
                    <div class="target-recommended-race">
                      <i data-lucide="compass"></i>
                      <span>推奨次走: <b>${t.recommendedRace}</b></span>
                    </div>
                  ` : ''}
                </div>
              </div>
            `;
          }).join('');
        }

        // Historical Next Race Stats
        let histStatsHtml = '';
        if (data.nextRaceInsights && data.nextRaceInsights.historicalNextRaceStats) {
          const hStats = data.nextRaceInsights.historicalNextRaceStats;
          histStatsHtml = `
            <div class="historical-stats-card">
              <div class="stats-card-title">
                <i data-lucide="trending-up"></i>
                <span>${hStats.title}</span>
              </div>
              <div class="stats-grid-row">
                ${hStats.stats.map(s => `
                  <div class="stat-item-box">
                    <div class="stat-item-label">${s.label}</div>
                    <div class="stat-item-value">${s.value}</div>
                  </div>
                `).join('')}
              </div>
            </div>
          `;
        }

        container.innerHTML = `
          <!-- 1. レース概要＆サマリーカード -->
          <div class="review-card">
            <div class="review-race-hero">
              <div class="review-race-hero-top">
                <div>
                  <h2 class="review-race-hero-title">${data.raceName}</h2>
                  <div class="review-meta-row">
                    <span class="review-meta-tag"><i data-lucide="calendar" style="width:12px;height:12px;display:inline;margin-right:4px;"></i>${data.date}</span>
                    <span class="review-meta-tag"><i data-lucide="map-pin" style="width:12px;height:12px;display:inline;margin-right:4px;"></i>${data.venue} ${data.course}</span>
                    <span class="review-meta-tag">馬場: <b>${data.trackCondition}</b> (${data.weather})</span>
                    <span class="review-meta-tag">クッション値: <b>${data.cushionValue}</b></span>
                    ${(() => {
                      const lvl = (typeof data.raceLevel === 'object' && data.raceLevel) ? data.raceLevel : { rating: 5, label: String(data.raceLevel || 'S級') };
                      const count = Math.min(5, Math.max(1, Math.floor(lvl.rating || 5)));
                      return `<span class="review-meta-tag">レース評価: <b style="color:#fbbf24;">${'★'.repeat(count)} ${lvl.label}</b></span>`;
                    })()}
                  </div>
                </div>

                <div class="review-winner-podium">
                  <div class="review-winner-crown">🏆</div>
                  <div class="review-winner-info">
                    <div style="font-size:11px;font-weight:700;color:#94a3b8;">勝ち馬</div>
                    <div class="review-winner-name" onclick="openHorseDetail('${data.winner.name}')" style="cursor: pointer;" title="クリックして競走馬詳細を見る">${data.winner.name}</div>
                    <div class="review-winner-sub">${data.winner.jockey} (${data.winner.pop}人気 / ${data.winningTime})</div>
                  </div>
                </div>
              </div>

              <div class="review-summary-text">
                <div style="font-size:12px;font-weight:800;color:#34d399;margin-bottom:4px;">【レース展開総括】</div>
                ${data.summary}
              </div>
            </div>
          </div>

          <!-- 2. ペース＆トラックバイアス・ラップ分析 -->
          <div class="review-card">
            <div class="review-card-header">
              <h3 class="review-card-title"><i data-lucide="gauge"></i> 展開・ペース＆トラックバイアス分析</h3>
            </div>

            <div class="pace-bias-grid">
              <div class="pace-box">
                <div class="pace-box-header"><i data-lucide="timer" style="width:15px;height:15px;"></i> レースペース判定</div>
                <div class="pace-type-badge">${data.pace.paceType}</div>
                <div class="pace-split-row">
                  <span>前半1000m: <b>${data.pace.front1000m}秒</b></span>
                  <span>後半1000m: <b>${data.pace.back1000m}秒</b></span>
                </div>
                <p class="pace-desc">${data.pace.comment}</p>
              </div>

              <div class="bias-box">
                <div class="bias-box-header"><i data-lucide="layers" style="width:15px;height:15px;"></i> トラックバイアス（馬場傾向）</div>
                <div style="font-size:13.5px;font-weight:700;color:#34d399;margin-bottom:6px;">${data.trackBias.advantage}</div>
                <p class="bias-desc">${data.trackBias.courseCondition}</p>
              </div>
            </div>

            ${lapBarsHtml}
          </div>

          <!-- 3. 【好走ランク vs 確定着順】事前期待度と実際の結果・乖離分析 -->
          <div class="review-card contender-deviation-card">
            <div class="review-card-header">
              <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;">
                <h3 class="review-card-title">
                  <i data-lucide="crosshair"></i> 事前好走ランク vs 確定着順（乖離度・精度分析）
                </h3>
                <span class="deviation-header-pill">6大ファクター検証</span>
              </div>
              <span style="font-size:11.5px;color:#94a3b8;">事前評価と実際の結果のズレを徹底検証</span>
            </div>

            <!-- KPIサマリーハイライトカード -->
            <div class="deviation-kpi-grid">
              <div class="dev-kpi-card highlight-match">
                <div class="dev-kpi-label">🎯 上位指名馬の好走実績</div>
                <div class="dev-kpi-title">${matchTitle}</div>
                <div class="dev-kpi-sub">${matchSub}</div>
              </div>
              <div class="dev-kpi-card highlight-surge">
                <div class="dev-kpi-label">⚡ 最大激走馬（大幅上振れ）</div>
                <div class="dev-kpi-title">${surgeTitle}</div>
                <div class="dev-kpi-sub">${surgeSub}</div>
              </div>
              <div class="dev-kpi-card highlight-drop">
                <div class="dev-kpi-label">⚠️ 最大凡走馬（下振れ・波乱）</div>
                <div class="dev-kpi-title">${dropTitle}</div>
                <div class="dev-kpi-sub">${dropSub}</div>
              </div>
            </div>

            <!-- コントロールバー（ソート切り替え） -->
            <div class="deviation-control-bar">
              <span class="dev-control-label">並び替え:</span>
              <div class="dev-sort-btn-group">
                <button class="btn-dev-sort active" data-sort="rank" onclick="setDeviationSort('rank')">📌 好走ランク順</button>
                <button class="btn-dev-sort" data-sort="finish" onclick="setDeviationSort('finish')">🏆 確定着順順</button>
                <button class="btn-dev-sort" data-sort="surge" onclick="setDeviationSort('surge')">⚡ 激走馬 (上振れ順)</button>
                <button class="btn-dev-sort" data-sort="drop" onclick="setDeviationSort('drop')">⚠️ 凡走馬 (下振れ順)</button>
              </div>
            </div>

            <!-- 対比テーブル -->
            <div class="deviation-table-wrapper">
              <table class="deviation-table">
                <thead>
                  <tr>
                    <th style="width: 140px; white-space: nowrap;">好走ランク</th>
                    <th style="min-width: 180px; white-space: nowrap;">馬番・馬名</th>
                    <th style="width: 90px; text-align: center; white-space: nowrap;">確定着順</th>
                    <th style="width: 90px; text-align: center; white-space: nowrap;">単勝人気</th>
                    <th style="width: 140px; text-align: center; white-space: nowrap;">着順乖離度</th>
                    <th style="min-width: 240px;">乖離の核心要因・レース回顧</th>
                  </tr>
                </thead>
                <tbody id="deviation-table-body"></tbody>
              </table>
            </div>
          </div>

          <!-- 4. 【★最重要★】次回への参考データ＆狙い目診断 -->
          <div class="review-card" style="border: 1px solid rgba(16, 185, 129, 0.4); background: linear-gradient(135deg, rgba(16, 185, 129, 0.05) 0%, rgba(30, 41, 59, 0.8) 100%);">
            <div class="review-card-header">
              <h3 class="review-card-title" style="color: #34d399;">
                <i data-lucide="target" style="color: #34d399;"></i> 次回への参考データ＆狙い目診断
              </h3>
              <span style="font-size: 11px; font-weight: 700; color: #94a3b8;">馬券直結・次走注目馬リスト</span>
            </div>

            <div class="next-insights-container">
              <!-- 注目馬・危険馬カードグリッド -->
              <div class="pickup-horses-grid">
                ${targetHorsesHtml}
              </div>

              <!-- 過去10年の次走傾向データ -->
              ${histStatsHtml}

              <!-- 血統・適性アドバイス -->
              ${data.nextRaceInsights && data.nextRaceInsights.pedigreeInsights ? `
                <div class="pedigree-insight-box">
                  <i data-lucide="dna"></i>
                  <div>
                    <span style="font-weight: 800; color: #c084fc; margin-right: 6px;">【血統・舞台適性からの次走狙い目】</span>
                    <span>${data.nextRaceInsights.pedigreeInsights}</span>
                  </div>
                </div>
              ` : ''}
            </div>
          </div>

          <!-- 5. 出走馬 個別詳細回顧テーブル -->
          <div class="review-card">
            <div class="review-card-header">
              <h3 class="review-card-title"><i data-lucide="list-ordered"></i> 出走各馬のレース個別回顧＆勝因・敗因</h3>
            </div>

            <div class="review-filter-bar">
              <button class="btn-review-filter active" data-filter="all" onclick="setReviewFilter('all')">全頭表示</button>
              <button class="btn-review-filter" data-filter="pickup" onclick="setReviewFilter('pickup')">🎯 次走注目・危険馬</button>
              <button class="btn-review-filter" data-filter="podium" onclick="setReviewFilter('podium')">🏆 上位入線（1〜3着）</button>
              <button class="btn-review-filter" data-filter="disadvantage" onclick="setReviewFilter('disadvantage')">⚠️ 不利・敗因あり</button>
            </div>

            <div id="horse-reviews-list-container" class="horse-review-list"></div>
          </div>
        `;

        renderDeviationTable(raceId);
        renderFilteredHorsesList();
        if (typeof lucide !== 'undefined') lucide.createIcons();
      }



      function openRaceDetail(id, updateRoute = true) {
        const race = G1_RACES.find(r => r.id === String(id));
        if (!race) return;

        if (updateRoute && typeof window !== 'undefined') {
          const targetHash = '#race-' + id;
          if (window.location.hash !== targetHash) {
            window.location.hash = targetHash;
          }
          if (typeof localStorage !== 'undefined') {
            localStorage.setItem('keiba_active_route', targetHash);
          }
        }

        const modal = document.getElementById('modal-race-detail');
        const title = document.getElementById('detail-modal-title');
        const body = document.getElementById('detail-modal-body');

        if (!modal || !title || !body) return;

        title.innerText = `${race.name} (G1) 詳細`;

        const raceDate = new Date(race.date);
        const formattedDate = raceDate.toLocaleDateString('ja-JP', {
          year: 'numeric', month: 'long', day: 'numeric', weekday: 'short'
        });

        const entries = typeof ENTRIES_DATA !== 'undefined' ? ENTRIES_DATA[id] : null;

        let historyTableRows = '';
        let historyData = (typeof HISTORICAL_DATA !== 'undefined' && HISTORICAL_DATA[id]) ? HISTORICAL_DATA[id] : [];
        const fullHistoryMap = (typeof HISTORICAL_FULL_RESULTS !== 'undefined' && HISTORICAL_FULL_RESULTS[id]) ? HISTORICAL_FULL_RESULTS[id] : {};

        if ((!historyData || historyData.length === 0) && fullHistoryMap && Object.keys(fullHistoryMap).length > 0) {
          const sortedYears = Object.keys(fullHistoryMap).sort((a, b) => parseInt(b) - parseInt(a));
          historyData = sortedYears.map(y => {
            const list = fullHistoryMap[y];
            const winner = list.find(h => h.rank === 1) || list[0];
            return [
              parseInt(y),
              winner ? winner.horseName : '-',
              winner ? winner.jockey : '-',
              winner ? winner.time : '-',
              winner ? (parseInt(winner.pop) || 1) : 1,
              winner ? winner.stable : '-'
            ];
          });
        }

        historyData.forEach((h, hIdx) => {
          const year = h[0];
          const fullList = fullHistoryMap[year] || [];
          
          let fullRowsHtml = '';
          fullList.forEach(m => {
            let rankBadge = m.rank;
            let rankClass = 'rank-other';
            if (m.rank === 1) rankClass = 'rank-1';
            else if (m.rank === 2) rankClass = 'rank-2';
            else if (m.rank === 3) rankClass = 'rank-3';

            fullRowsHtml += `
              <tr style="border-bottom: 1px solid rgba(255,255,255,0.04);">
                <td style="text-align: center;"><span class="rank-badge ${rankClass}" style="width:20px;height:20px;font-size:11px;">${rankBadge}</span></td>
                <td style="text-align: center; font-family: monospace; font-weight: 700;"><span class="nh-gate-cell waku-${m.waku || 1}" style="width:20px;height:20px;font-size:11px;border-radius:3px;display:inline-flex;">${m.gate}</span></td>
                <td style="font-weight: 700; color: #fff;">${m.horseName}</td>
                <td>${m.sexAge}</td>
                <td>${m.load}</td>
                <td>${m.jockey}</td>
                <td style="font-family: monospace; font-weight: 600;">${m.time}</td>
                <td>${m.margin}</td>
                <td style="font-size: 11px; color: var(--text-muted);">${m.passing}</td>
                <td style="font-family: monospace;">${m.last3F}</td>
                <td style="font-family: monospace;">${m.odds}</td>
                <td>${m.pop}</td>
                <td>${m.weight}</td>
                <td style="font-size: 12px; color: var(--text-muted);">${m.stable}</td>
              </tr>
            `;
          });

          const subTableHtml = fullList.length > 0 ? `
            <tr id="history-detail-${id}-${year}" class="history-detail-row" style="display: none; background: rgba(0,0,0,0.5);">
              <td colspan="6" style="padding: 12px 8px;">
                <div style="font-size: 12px; font-weight: 700; color: var(--gold); margin-bottom: 8px;">
                  📋 ${year}年 全着順・詳細データ (${fullList.length}頭出走)
                </div>
                <div class="table-scroll-container" style="max-height: 320px; overflow-y: auto;">
                  <table class="result-table" style="font-size: 11px; width: 100%;">
                    <thead>
                      <tr style="position: sticky; top: 0; background: #13231d; z-index: 2;">
                        <th style="width: 32px; text-align: center;">着</th>
                        <th style="width: 32px; text-align: center;">番</th>
                        <th>馬名</th>
                        <th>性齢</th>
                        <th>斤量</th>
                        <th>騎手</th>
                        <th>タイム</th>
                        <th>着差</th>
                        <th>通過</th>
                        <th>上り</th>
                        <th>単勝</th>
                        <th>人気</th>
                        <th>馬体重</th>
                        <th>厩舎</th>
                      </tr>
                    </thead>
                    <tbody>
                      ${fullRowsHtml}
                    </tbody>
                  </table>
                </div>
              </td>
            </tr>
          ` : '';

          historyTableRows += `
            <tr class="history-year-row" data-year="${year}" data-race-id="${id}" style="cursor: pointer;" title="クリックで全頭成績を展開">
              <td style="text-align: center; font-family: monospace; font-weight: 700; color: var(--gold);">
                ${year} <i data-lucide="chevron-right" class="toggle-icon" style="width: 12px; height: 12px; display: inline-block; transition: transform 0.2s;"></i>
              </td>
              <td style="font-weight: 700; color: #fff;">${h[1]}</td>
              <td>${h[2]}</td>
              <td style="font-family: monospace;">${h[3]}</td>
              <td>${h[4]}人気</td>
              <td style="font-size: 12px; color: var(--text-muted);">${h[5]}</td>
            </tr>
            ${subTableHtml}
          `;
        });

        let innerHTML = '';

        if (race.status === 'finished') {
          innerHTML = `
            <div class="modal-tabs-header">
              <div class="modal-tabs">
                <button class="modal-tab-btn active" data-tab="result">
                  <i data-lucide="trophy"></i>
                  <span>レース結果・全着順</span>
                </button>
                <button class="modal-tab-btn" data-tab="payouts">
                  <i data-lucide="coins"></i>
                  <span>払戻金一覧</span>
                </button>
                <button class="modal-tab-btn" data-tab="history">
                  <i data-lucide="history"></i>
                  <span>歴代優勝馬（過去10年）</span>
                </button>
              </div>
              <button class="btn-modal-to-review" onclick="closeModal(); selectReviewRace('${id}'); switchView('review', true, true);">
                <i data-lucide="file-text"></i>
                <span>レース回顧・次走分析を見る</span>
                <i data-lucide="arrow-right"></i>
              </button>
            </div>

            <div id="modal-tab-content-result" class="modal-tab-content">
              ${(typeof PREDICTION_DATA !== 'undefined' && PREDICTION_DATA.races && PREDICTION_DATA.races[id]) ? `
                <div style="background: linear-gradient(135deg, rgba(245, 158, 11, 0.15), rgba(16, 185, 129, 0.15)); border: 1px solid var(--gold); border-radius: 10px; padding: 12px 16px; margin-bottom: 16px; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 8px;">
                  <div>
                    <div style="font-size: 14px; font-weight: 800; color: #fff;">🎯 ${race.name} 専用の「予想・攻略分析」を見る</div>
                    <div style="font-size: 12px; color: var(--text-muted); margin-top: 2px;">netkeibaオッズ・調教評価・Xオカルトサイン・打った印の振り返り</div>
                  </div>
                  <button class="btn-jump-prediction" data-race-id="${id}" style="background: var(--gold); color: #111; border: none; padding: 8px 16px; border-radius: 6px; font-weight: 800; font-size: 12px; cursor: pointer;">
                    予想・攻略を見る ➔
                  </button>
                </div>
              ` : ''}

              <div class="detail-meta-grid">
                <div class="detail-meta-item">
                  <span class="detail-meta-label">開催日 / 発走時刻</span>
                  <span class="detail-meta-value">${formattedDate} 15:40</span>
                </div>
                <div class="detail-meta-item">
                  <span class="detail-meta-label">開催場 / コース</span>
                  <span class="detail-meta-value">${race.location}競馬場 | ${race.course}</span>
                </div>
                <div class="detail-meta-item">
                  <span class="detail-meta-label">天候 / 馬場状態</span>
                  <span class="detail-meta-value">${race.weather || '晴'} / ${race.trackCondition || '良'} (クッション値: ${race.cushionValue || '9.5'})</span>
                </div>
                <div class="detail-meta-item">
                  <span class="detail-meta-label">優勝馬 / 騎手</span>
                  <span class="detail-meta-value" style="color: var(--gold); font-weight: 700;">
                    ${race.winner} (${race.winnerJockey})
                  </span>
                </div>
              </div>

              <h3 class="detail-section-title">全着順確定結果</h3>
              <div class="table-scroll-container">
                <table class="result-table">
                  <thead>
                    <tr>
                      <th style="width: 44px; text-align: center;">着順</th>
                      <th style="width: 44px; text-align: center;">馬番</th>
                      <th>馬名</th>
                      <th>性齢</th>
                      <th>斤量</th>
                      <th>騎手</th>
                      <th>タイム</th>
                      <th>着差</th>
                      <th>通過順</th>
                      <th>上がり3F</th>
                      <th>単勝オッズ</th>
                      <th>人気</th>
                      <th>馬体重</th>
                      <th>調教師</th>
                    </tr>
                  </thead>
                  <tbody>
                    ${(() => {
                      const rawRes = RESULTS_DATA[id];
                      const rList = Array.isArray(rawRes) ? rawRes : (rawRes && rawRes.horses ? rawRes.horses : []);
                      const totalHorses = rList.length;
                      return rList.map(r => {
                        let rankBadge = r[0];
                        let rankClass = 'rank-other';
                        if (r[0] === 1) rankClass = 'rank-1';
                        else if (r[0] === 2) rankClass = 'rank-2';
                        else if (r[0] === 3) rankClass = 'rank-3';

                        let wakuColor = 1;
                        const gateNum = Number(r[1]);
                        if (gateNum > 0 && totalHorses > 0) {
                          wakuColor = Math.min(8, Math.max(1, Math.ceil(gateNum / (totalHorses / 8))));
                        }

                      return `
                        <tr>
                          <td style="text-align: center;"><span class="rank-badge ${rankClass}">${rankBadge}</span></td>
                          <td style="text-align: center; font-family: monospace; font-weight: 700;"><span class="nh-gate-cell waku-${wakuColor}" style="width:24px;height:24px;font-size:12px;border-radius:4px;display:inline-flex;">${r[1]}</span></td>
                          <td style="font-weight: 700; color: #fff;">${r[2]}</td>
                          <td>${r[3]}</td>
                          <td>${r[4]}</td>
                          <td>${r[5]}</td>
                          <td style="font-family: monospace; font-weight: 600;">${r[6]}</td>
                          <td>${r[7]}</td>
                          <td style="font-size: 12px; color: var(--text-muted);">${r[8]}</td>
                          <td style="font-family: monospace;">${r[9]}</td>
                          <td style="font-family: monospace;">${r[10]}</td>
                          <td>${r[11]}</td>
                          <td>${r[12]}${r[13] ? ` (${r[13]})` : ''}</td>
                          <td style="font-size: 13px; color: var(--text-muted);">${r[14] || '-'}</td>
                        </tr>
                      `;
                      }).join('');
                    })()}
                  </tbody>
                </table>
              </div>
            </div>

            <div id="modal-tab-content-payouts" class="modal-tab-content" style="display: none;">
              <h3 class="detail-section-title">払戻金確定情報</h3>
              <div class="payouts-grid">
                ${(() => {
                  let pList = [];
                  if (PAYOUTS_DATA[id]) {
                    if (Array.isArray(PAYOUTS_DATA[id])) {
                      pList = PAYOUTS_DATA[id];
                    } else if (PAYOUTS_DATA[id].payoutsList) {
                      pList = PAYOUTS_DATA[id].payoutsList;
                    }
                  }
                  if (pList.length === 0 && RESULTS_DATA[id] && RESULTS_DATA[id].payouts) {
                    pList = RESULTS_DATA[id].payouts;
                  }
                  if (pList.length === 0 && race) {
                    pList = hydratePayouts(race) || [];
                  }
                  return pList.map(p => {
                    let popDisplay = "";
                    if (p.pop) {
                      const parts = String(p.pop).split("<br>").map(x => x.includes("人気") ? x : (x ? x + "人気" : ""));
                      popDisplay = parts.join("<br>");
                    }
                    return `
                      <div class="payout-item">
                        <div style="display: flex; align-items: center; gap: 10px;">
                          <span class="payout-type">${p.type}</span>
                          <span class="payout-comb">${p.comb}</span>
                        </div>
                        <div style="display: flex; align-items: center; gap: 10px; text-align: right;">
                          <span class="payout-value">${p.val}</span>
                          ${popDisplay ? `<span class="payout-pop">${popDisplay}</span>` : ""}
                        </div>
                      </div>
                    `;
                  }).join("");
                })()}
              </div>
            </div>

            <div id="modal-tab-content-history" class="modal-tab-content" style="display: none;">
              <h3 class="detail-section-title">過去10年の歴代優勝馬（傾向分析）</h3>
              <p style="font-size: 12px; color: var(--text-muted); margin-bottom: 12px;">各年をクリックすると、該当年の全頭着順一覧が展開されます。</p>
              <div class="table-scroll-container">
                <table class="result-table" style="width: 100%;">
                  <thead>
                    <tr>
                      <th style="width: 80px; text-align: center;">開催年</th>
                      <th>優勝馬</th>
                      <th>騎手</th>
                      <th>タイム</th>
                      <th>人気</th>
                      <th>調教師</th>
                    </tr>
                  </thead>
                  <tbody>
                    ${historyTableRows}
                  </tbody>
                </table>
              </div>
            </div>
          `;
        } else if (entries && entries.length > 0) {
          innerHTML = `
            <div class="modal-tabs-header">
              <div class="modal-tabs">
                <button class="modal-tab-btn active" data-tab="entries">
                  <i data-lucide="list"></i>
                  <span>出馬表・登録馬一覧</span>
                </button>
                <button class="modal-tab-btn" data-tab="history">
                  <i data-lucide="history"></i>
                  <span>歴代優勝馬（過去10年）</span>
                </button>
              </div>
              <button class="btn-modal-to-pred btn-jump-prediction" data-race-id="${id}" onclick="closeModal();">
                <i data-lucide="sparkles"></i>
                <span>予想・オカルト攻略を見る</span>
                <i data-lucide="arrow-right"></i>
              </button>
            </div>

            <div id="modal-tab-content-entries" class="modal-tab-content">
              <!-- 予想・オカルト誘導プレミアムバナー -->
              <div style="background: linear-gradient(135deg, rgba(245, 158, 11, 0.18), rgba(16, 185, 129, 0.18)); border: 1px solid var(--gold); border-radius: 12px; padding: 14px 16px; margin-bottom: 16px; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; box-shadow: 0 4px 14px rgba(245, 158, 11, 0.15);">
                <div>
                  <div style="font-size: 15px; font-weight: 800; color: #fff; display: flex; align-items: center; gap: 6px;">
                    🎯 <span>${race.name} 専用の「予想・攻略分析＆Xオカルト」公開中！</span>
                  </div>
                  <div style="font-size: 12px; color: var(--text-muted); margin-top: 3px;">
                    netkeiba想定オッズ・調教評価・X話題オカルトサイン・印管理を完備
                  </div>
                </div>
                <button class="btn-jump-prediction" data-race-id="${id}" style="background: var(--gold); color: #111; border: none; padding: 10px 18px; border-radius: 8px; font-weight: 800; font-size: 13px; cursor: pointer; display: flex; align-items: center; gap: 6px; box-shadow: 0 4px 12px rgba(245, 158, 11, 0.3);">
                  予想・オカルトを見る ➔
                </button>
              </div>

              <div class="detail-meta-grid">
                <div class="detail-meta-item">
                  <span class="detail-meta-label">開催日 / 発走時刻</span>
                  <span class="detail-meta-value">${formattedDate} 15:40</span>
                </div>
                <div class="detail-meta-item">
                  <span class="detail-meta-label">開催場 / コース</span>
                  <span class="detail-meta-value">${race.location}競馬場 | ${race.course}</span>
                </div>
                <div class="detail-meta-item">
                  <span class="detail-meta-label">条件 / 登録頭数</span>
                  <span class="detail-meta-value">${race.name.includes('女王杯') || race.name.includes('フィリーズ') ? '牝馬限定' : 'オープン'} / 全${entries.length}頭</span>
                </div>
                <div class="detail-meta-item">
                  <span class="detail-meta-label">出馬表ステータス</span>
                  <span class="detail-meta-value" style="font-weight: 700;">
                    ${(() => {
                      const stage = getRaceEntryStage(id);
                      if (stage === 'gate_confirmed') {
                        return `<span class="badge-stage-gates">🎯 枠順確定済 (出走${entries.length}頭)</span>`;
                      } else if (stage === 'starters_confirmed') {
                        return `<span class="badge-stage-confirmed">🏇 出走馬確定 (枠順未定・五十音順・全${entries.length}頭)</span>`;
                      } else {
                        return `<span class="badge-stage-scheduled">📋 出馬予定 (枠順未定・五十音順・全${entries.length}頭)</span>`;
                      }
                    })()}
                  </span>
                </div>
              </div>

              <h3 class="detail-section-title">
                ${(() => {
                  const stage = getRaceEntryStage(id);
                  if (stage === 'gate_confirmed') return '出走馬・確定枠順一覧';
                  if (stage === 'starters_confirmed') return '出走決定馬一覧（五十音順）';
                  return '出走登録馬・出馬予定一覧（五十音順）';
                })()}
              </h3>
              <div class="table-scroll-container">
                <table class="result-table">
                  <thead>
                    <tr>
                      <th style="width: 44px; text-align: center;">番</th>
                      <th style="width: 44px; text-align: center;">枠</th>
                      <th>馬名</th>
                      <th>性齢</th>
                      <th>斤量</th>
                      <th>想定騎手</th>
                      <th>所属厩舎</th>
                      <th>想定オッズ</th>
                      <th>馬体重</th>
                      <th>調教/状態</th>
                    </tr>
                  </thead>
                  <tbody>
                    ${(() => {
                      const stage = getRaceEntryStage(id);
                      const isGateConfirmed = (stage === 'gate_confirmed');
                      const predStarters = (typeof PREDICTION_DATA !== 'undefined' && PREDICTION_DATA.races && PREDICTION_DATA.races[id]) 
                        ? PREDICTION_DATA.races[id].starters 
                        : null;

                      let sortedEntries = [...entries];
                      if (isGateConfirmed) {
                        sortedEntries.sort((a, b) => (a.gate || 99) - (b.gate || 99));
                      } else {
                        // 枠順確定するまでは五十音順
                        sortedEntries.sort((a, b) => a.horseName.localeCompare(b.horseName, 'ja'));
                      }

                      return sortedEntries.map(e => {
                        const pHorse = predStarters ? predStarters.find(s => s.horseName === e.horseName || (isGateConfirmed && s.gate === e.gate)) : null;
                        const oddsVal = pHorse ? (pHorse.odds ? pHorse.odds + '倍' : '--') : '--';
                        const popVal = pHorse ? `(${pHorse.pop}人気)` : '';

                        let weightVal = '-';
                        if (pHorse) {
                          if (pHorse.confirmedWeight) {
                            weightVal = `${pHorse.confirmedWeight}kg`;
                          } else if (pHorse.trainingWeight) {
                            let diffStr = '';
                            if (pHorse.lastRaceWeight) {
                              const d = pHorse.trainingWeight - pHorse.lastRaceWeight;
                              diffStr = d > 0 ? ` (+${d})` : (d === 0 ? ' (±0)' : ` (${d})`);
                            }
                            weightVal = `${pHorse.trainingWeight}kg <span class="weight-tag-pre" style="font-size:10px;">調教後${diffStr}</span>`;
                          } else if (pHorse.lastRaceWeight || pHorse.prevWeight) {
                            weightVal = `${pHorse.lastRaceWeight || pHorse.prevWeight}kg <span class="weight-tag-prev" style="font-size:10px;">前走</span>`;
                          }
                        }

                        let gradeVal = '-';
                        if (pHorse && pHorse.trainingGrade && pHorse.trainingGrade !== '-' && pHorse.trainingGrade !== 'null') {
                          gradeVal = `【${pHorse.trainingGrade}】`;
                        }

                        let gateColHtml = '';
                        let wakuColHtml = '';
                        if (isGateConfirmed && e.gate) {
                          gateColHtml = `<span class="nh-gate-cell waku-${e.waku || 1}" style="width:24px;height:24px;font-size:12px;border-radius:4px;display:inline-flex;">${e.gate}</span>`;
                          wakuColHtml = `<td style="text-align: center; font-weight: 700; color: var(--text-muted);">${e.waku || 1}枠</td>`;
                        } else {
                          gateColHtml = `<span class="nh-gate-cell unconfirmed" style="width:24px;height:24px;font-size:12px;border-radius:4px;display:inline-flex;" title="枠順未確定">-</span>`;
                          wakuColHtml = `<td style="text-align: center; font-size: 11px; color: var(--text-muted);">未定</td>`;
                        }

                        return `
                          <tr>
                            <td style="text-align: center; font-family: monospace; font-weight: 700;">
                              ${gateColHtml}
                            </td>
                            ${wakuColHtml}
                            <td style="font-weight: 700; color: #fff;">
                              <div>${e.horseName}</div>
                              ${pHorse && pHorse.pedigree ? `<div style="font-size:10px;color:var(--text-muted);font-weight:normal;">父:${pHorse.pedigree.sire} (母父:${pHorse.pedigree.broodmareSire})</div>` : ''}
                              ${pHorse && pHorse.prevRace ? `<div style="font-size:10px;color:#a7f3d0;font-weight:normal;">前走: ${pHorse.prevRace.raceName} ${pHorse.prevRace.finish} (${pHorse.prevRace.agari || ''})</div>` : ''}
                            </td>
                            <td>${e.sexAge}</td>
                            <td>${e.load}kg</td>
                            <td>${e.jockey}</td>
                            <td style="font-size: 12px; color: var(--text-muted);">${e.stable}</td>
                            <td style="font-family: monospace; font-weight: 700; color: var(--gold);">${oddsVal} <span style="font-size:11px;color:var(--text-muted);">${popVal}</span></td>
                            <td style="font-family: monospace; font-size: 12px;">${weightVal}</td>
                            <td style="font-size: 12px;">${gradeVal}</td>
                          </tr>
                        `;
                      }).join('');
                    })()}
                  </tbody>
                </table>
              </div>
            </div>

            <div id="modal-tab-content-history" class="modal-tab-content" style="display: none;">
              <h3 class="detail-section-title">過去10年の歴代優勝馬（傾向分析）</h3>
              <p style="font-size: 12px; color: var(--text-muted); margin-bottom: 12px;">各年をクリックすると、該当年の全頭着順一覧が展開されます。</p>
              <div class="table-scroll-container">
                <table class="result-table" style="width: 100%;">
                  <thead>
                    <tr>
                      <th style="width: 80px; text-align: center;">開催年</th>
                      <th>優勝馬</th>
                      <th>騎手</th>
                      <th>タイム</th>
                      <th>人気</th>
                      <th>調教師</th>
                    </tr>
                  </thead>
                  <tbody>
                    ${historyTableRows}
                  </tbody>
                </table>
              </div>
            </div>
          `;
        } else {
          innerHTML = `
            <div class="modal-tabs-header">
              <div class="modal-tabs">
                <button class="modal-tab-btn active" data-tab="history">
                  <i data-lucide="history"></i>
                  <span>歴代優勝馬（過去10年）</span>
                </button>
              </div>
            </div>
            <div id="modal-tab-content-history" class="modal-tab-content">
              <div class="table-scroll-container">
                <table class="result-table" style="width: 100%;">
                  <thead>
                    <tr>
                      <th style="width: 80px; text-align: center;">開催年</th>
                      <th>優勝馬</th>
                      <th>騎手</th>
                      <th>タイム</th>
                      <th>人気</th>
                      <th>調教師</th>
                    </tr>
                  </thead>
                  <tbody>
                    ${historyTableRows}
                  </tbody>
                </table>
              </div>
            </div>
          `;
        }

        body.innerHTML = innerHTML;

        // タブ切替バインド
        const modalTabBtns = modal.querySelectorAll('.modal-tab-btn');
        modalTabBtns.forEach(btn => {
          btn.addEventListener('click', () => {
            modalTabBtns.forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
            const tabName = btn.getAttribute('data-tab');
            modal.querySelectorAll('.modal-tab-content').forEach(c => c.style.display = 'none');
            const targetContent = document.getElementById(`modal-tab-content-${tabName}`);
            if (targetContent) targetContent.style.display = 'block';
          });
        });

        // 過去年度の全頭展開アコーディオン
        modal.querySelectorAll('.history-year-row').forEach(row => {
          row.addEventListener('click', () => {
            const y = row.getAttribute('data-year');
            const rId = row.getAttribute('data-race-id');
            const detailRow = document.getElementById(`history-detail-${rId}-${y}`);
            const icon = row.querySelector('.toggle-icon');
            if (!detailRow) return;
            const isHidden = detailRow.style.display === 'none';
            detailRow.style.display = isHidden ? 'table-row' : 'none';
            if (icon) {
              icon.style.transform = isHidden ? 'rotate(90deg)' : 'none';
            }
          });
        });

        // 予想ページへのジャンプボタン
        modal.querySelectorAll('.btn-jump-prediction').forEach(btn => {
          btn.addEventListener('click', (e) => {
            const targetRaceId = btn.getAttribute('data-race-id');
            closeModal();
            if (typeof setPredictionRace === 'function') {
              setPredictionRace(targetRaceId);
            }
            navigateTo('#prediction-' + targetRaceId);
          });
        });

        // モーダル表示
        modal.classList.add('open', 'active');
        document.body.style.overflow = 'hidden';
        refreshIcons();
      }



      function initApp() {
        if (typeof localStorage !== 'undefined') {
          const savedFilter = localStorage.getItem('keiba_calendar_filter');
          if (savedFilter) {
            currentFilter = savedFilter;
            const targetBtn = document.querySelector(`.tab-btn[data-filter="${savedFilter}"]`);
            if (targetBtn) {
              const tabBtns = document.querySelectorAll('.tab-btn');
              tabBtns.forEach(b => b.classList.remove('active'));
              targetBtn.classList.add('active');
            }
          }
        }

        initEventListeners();
        initPredictionEventListeners();

        if (typeof autoLifecycleEngine === 'function') autoLifecycleEngine();
        renderRaces();
        updateTabCounts();
        startNextRaceCountdown();

        handleRoute(false);

        if (typeof window !== 'undefined') {
          const urlParams = window.location ? new URLSearchParams(window.location.search) : null;
          if (urlParams && urlParams.has('horse')) {
            setTimeout(() => {
              openHorseDetail(urlParams.get('horse'));
            }, 50);
          }
          window.addEventListener('hashchange', () => {
            handleRoute(false);
          });
        }

        if (typeof setInterval !== 'undefined') {
          if (typeof autoLifecycleEngine === 'function') setInterval(autoLifecycleEngine, 60000);
          if (typeof startOddsAutoRefresh === 'function') startOddsAutoRefresh();
        }
      }

      // Expose SPA functions to global window for inline onclick attributes
      if (typeof window !== 'undefined') {
        window.selectReviewRace = selectReviewRace;
        window.switchView = switchView;
        window.setReviewFilter = setReviewFilter;
        window.setDeviationSort = setDeviationSort;
        window.renderDeviationTable = renderDeviationTable;
        window.renderReviewPills = renderReviewPills;
        window.renderReviewContent = renderReviewContent;
        window.openRaceDetail = openRaceDetail;
        window.closeModal = closeModal;
        window.openHorseDetail = openHorseDetail;
        window.closeHorseModal = closeHorseModal;
        window.navigateTo = navigateTo;
        window.switchAppView = switchAppView;
        window.setPredictionRace = setPredictionRace;
        window.setUserMark = setUserMark;
        window.openMarkSheet = openMarkSheet;
        window.closeMarkSheet = closeMarkSheet;
        window.renderContenderRanking = renderContenderRanking;
        window.setRankingSort = setRankingSort;
        window.applyRankingToMarks = applyRankingToMarks;
        window.toggleRankingRowDetail = toggleRankingRowDetail;
        window.toggleAllRankingDrawers = toggleAllRankingDrawers;
        window.scrollToSection = scrollToSection;
      }

      if (typeof document !== 'undefined') {
        if (document.readyState === 'loading') {
          document.addEventListener('DOMContentLoaded', initApp);
        } else {
          initApp();
        }
      }
